var ROCKETS_INFO={"atlasCentaur":{"name":{"es":"Atlas-Centaur (Atlas LV-3C + Centaur D)","en":"Atlas-Centaur (Atlas LV-3C + Centaur D)"},"family":"Atlas-Centaur","heightM":34.4,"firstYear":1962,"blurb":{"es":"Su etapa superior Centaur fue el primer cohete de alta energía de Estados Unidos: quema hidrógeno líquido, que rinde cerca de un 40 % más que los combustibles de tipo queroseno.","en":"Its Centaur upper stage was the first high-energy rocket of the United States: it burns liquid hydrogen, which performs about 40 percent better than kerosene-type fuels."},"src":"https://ntrs.nasa.gov/api/citations/19660022877/downloads/19660022877.pdf"},"atlasCentaurTE":{"name":{"es":"Atlas-Centaur con tercera etapa TE-M-364-4","en":"Atlas-Centaur with TE-M-364-4 third stage"},"family":"Atlas-Centaur","heightM":40.3,"firstYear":1972,"blurb":{"es":"En 1972 voló por primera vez con una tercera etapa TE-M-364-4: un motor de combustible sólido que giraba como un trompo y dio a la Pioneer 10 unos 51.800 km/h, más que ninguna nave anterior.","en":"In 1972 it flew for the first time with a TE-M-364-4 third stage: a solid-fuel motor that spun like a top and gave Pioneer 10 about 51,800 km/h, more than any spacecraft before it."},"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},"saturnV":{"name":{"es":"Saturno V","en":"Saturn V"},"family":"Saturn V","heightM":111,"firstYear":1967,"blurb":{"es":"Era el cohete más potente que había volado con éxito: la NASA lo construyó con tres etapas para mandar personas a la Luna.","en":"It was the most powerful rocket that had ever flown successfully: NASA built it with three stages to send people to the Moon."},"src":"https://www.nasa.gov/learning-resources/for-kids-and-students/what-was-the-saturn-v-grades-5-8/"},"titan3e":{"name":{"es":"Titan IIIE-Centaur","en":"Titan IIIE-Centaur"},"family":"Titan IIIE-Centaur","heightM":48.8,"firstYear":1974,"blurb":{"es":"Unió el cohete Titan III, con dos grandes motores de combustible sólido a los costados, con la etapa superior Centaur, que quema hidrógeno y oxígeno líquidos.","en":"It joined the Titan III rocket, with two big solid rocket motors on its sides, to the Centaur upper stage, which burns liquid hydrogen and liquid oxygen."},"src":"https://ntrs.nasa.gov/api/citations/19750018961/downloads/19750018961.pdf"},"delta7925":{"name":{"es":"Delta II 7925","en":"Delta II 7925"},"family":"Delta II","heightM":39.6,"firstYear":1989,"blurb":{"es":"Un cohete de tres etapas con nueve propulsores de combustible sólido, seis encendidos en tierra y tres en vuelo; para 2003 este modelo ya sumaba más de 40 lanzamientos exitosos.","en":"A three-stage rocket with nine strap-on solid boosters, six lit on the pad and three in flight; by 2003 this model had more than 40 successful launches."},"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},"delta7925H":{"name":{"es":"Delta II 7925H (pesado)","en":"Delta II 7925H (Heavy)"},"family":"Delta II","heightM":39.6,"firstYear":1989,"blurb":{"es":"La H es de heavy, pesado: un Delta II más nuevo y un poco más potente, con nueve propulsores más anchos que dan alrededor de un 25 por ciento más de empuje.","en":"The H means heavy: a newer, slightly more powerful Delta II whose nine boosters are wider and give about 25 percent more thrust."},"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},"delta7925_10L":{"name":{"es":"Delta II 7925-10L","en":"Delta II 7925-10L"},"family":"Delta II","heightM":null,"firstYear":null,"blurb":{"es":"Es un Delta II con una cofia alargada de 3 metros de diámetro, que cubre también la segunda y la tercera etapa y donde entra el telescopio Kepler con su parasol.","en":"A Delta II with a stretched nose cone 3 metres across, which also covers the second and third stages and has room for the Kepler telescope and its sunshade."},"src":"https://www.jpl.nasa.gov/news/press_kits/Kepler-presskit-2-19-smfile.pdf"},"atlasV401":{"name":{"es":"Atlas V 401","en":"Atlas V 401"},"family":"Atlas V","heightM":57.3,"firstYear":2002,"blurb":{"es":"El Atlas V funciona como un juego de armar: la misma primera etapa puede volar sola, como acá, o con hasta cinco propulsores sólidos, y los tres números de su nombre dicen cómo se armó (cofia de 4 metros, 0 propulsores, 1 motor en la etapa superior).","en":"Atlas V works like a building kit: the same first stage can fly alone, as here, or with up to five solid boosters, and the three digits in its name tell how it was put together (4-metre nose cone, 0 boosters, 1 upper-stage engine)."},"src":"https://www.jpl.nasa.gov/news/press_kits/insight/launch/mission/"},"atlasV541":{"name":{"es":"Atlas V 541","en":"Atlas V 541"},"family":"Atlas V","heightM":60,"firstYear":2011,"blurb":{"es":"El mismo Atlas V con más fuerza: una cofia de 5 metros que también cubre la etapa superior Centaur y cuatro propulsores sólidos para dar más empuje en el despegue; este modelo ya había lanzado al rover Curiosity en 2011.","en":"The same Atlas V with more muscle: a 5-metre nose cone that also covers the Centaur upper stage, and four solid boosters for extra push at liftoff; this model had already launched the Curiosity rover in 2011."},"src":"https://www.jpl.nasa.gov/news/press_kits/mars_2020/launch/mission/"}};
var LAUNCH_SEQ={"surveyor1":{"rocket":"atlasCentaur","site":"cape","pad":"LC-36A","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"El Atlas-Centaur AC-10 espera en la plataforma 36A de Cabo Kennedy (hoy Cabo Cañaveral). Mide 34 metros y pesa unas 137 toneladas. Tras varios vuelos de prueba, este es su primer trabajo de verdad: llevar a Surveyor 1.","en":"Atlas-Centaur AC-10 waits on pad 36A at Cape Kennedy (now Cape Canaveral). It is 34 meters tall and weighs about 137 metric tons. After several test flights, this is its first real job: carrying Surveyor 1."},"src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"id":"liftoff","t":0,"title":{"es":"Despegue hacia la Luna","en":"Liftoff for the Moon"},"text":{"es":"30 de mayo de 1966, 14:41 (hora universal). Los tres motores grandes del Atlas se encienden juntos en el suelo: dos impulsores y uno central, el sustentador. Queman queroseno y oxígeno líquido.","en":"30 May 1966, 14:41 (Universal Time). The three big Atlas engines light together on the ground: two boosters and one in the middle, the sustainer. They burn kerosene and liquid oxygen."},"ignite":["boosterSection","stage1"],"src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"id":"boosterSection","t":145.1,"title":{"es":"Se sueltan dos motores","en":"Two engines drop away"},"text":{"es":"A los 142 segundos se apagan los dos motores impulsores y 3 segundos después se sueltan con su sección. El motor central sigue empujando. La pieza suelta vuelve a caer a la Tierra; no encontramos en qué lugar.","en":"At 142 seconds the two booster engines shut down, and 3 seconds later they drop away with their section. The middle engine keeps pushing. The dropped piece falls back to Earth; we could not find where."},"drop":["boosterSection"],"src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"id":"fairing","t":202.76,"title":{"es":"Fuera la cofia","en":"Nose fairing off"},"text":{"es":"La cofia era el escudo de Surveyor contra el aire. A los 176 segundos se van los cuatro paneles aislantes del Centaur y a los 203 la cofia se abre en dos mitades. Todo vuelve a caer a la Tierra; no encontramos dónde.","en":"The nose fairing was Surveyor's shield against the air. At 176 seconds the Centaur's four insulation panels come off, and at 203 the fairing opens into two halves. It all falls back to Earth; we could not find where."},"drop":["fairingA","fairingB"],"src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"id":"stage1","t":241.3,"title":{"es":"Adiós al Atlas","en":"Goodbye to the Atlas"},"text":{"es":"A los 239 segundos el Atlas agota su oxígeno líquido y se apaga, a unos 12.540 km/h. Una carga explosiva corta la unión y ocho cohetes chicos lo empujan hacia atrás. Vuelve a caer a la Tierra; no encontramos dónde.","en":"At 239 seconds the Atlas uses up its liquid oxygen and shuts down, at about 12,540 km/h. An explosive charge cuts the joint and eight small rockets push it backward. It falls back to Earth; we could not find where."},"drop":["stage1","interstage"],"speed_kmh":12540,"src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"id":"stage2Start","t":250.9,"title":{"es":"Se enciende el Centaur","en":"The Centaur lights up"},"text":{"es":"Casi 10 segundos después arrancan los dos motores RL-10 del Centaur. Queman hidrógeno y oxígeno líquidos, una mezcla muy potente, y van a empujar durante más de 7 minutos.","en":"Almost 10 seconds later the Centaur's two RL-10 engines start. They burn liquid hydrogen and liquid oxygen, a very powerful mix, and will push for more than 7 minutes."},"ignite":["stage2"],"src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"id":"stage2Cutoff","t":689.2,"title":{"es":"Directo a la Luna","en":"Straight to the Moon"},"text":{"es":"A los 689 segundos el Centaur se apaga cuando ya va a unos 37.850 km/h. No hizo falta dar vueltas a la Tierra: fue un ascenso directo, con un solo encendido, hacia el lugar donde iba a estar la Luna.","en":"At 689 seconds the Centaur shuts down, now going about 37,850 km/h. No laps around Earth were needed: it was a direct ascent, with a single burn, toward the place where the Moon would be."},"speed_kmh":37850,"src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"id":"separation","t":756.9,"title":{"es":"Surveyor vuela solo","en":"Surveyor flies alone"},"text":{"es":"A los 757 segundos tres resortes empujan a Surveyor 1, ya con las patas abiertas. El Centaur gira y suelta el combustible que le sobra para no chocar con la Luna. Quedó en una órbita muy alargada alrededor de la Tierra.","en":"At 757 seconds three springs push Surveyor 1 away, its legs already open. The Centaur turns and dumps its leftover propellant so it will not hit the Moon. It was left in a very stretched orbit around Earth."},"drop":["stage2"],"src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"}],"fates":[{"part":"boosterSection","name":{"es":"Sección de impulsores del Atlas (dos motores)","en":"Atlas booster section (two engines)"},"fate":{"es":"Se soltó a los 145 segundos, mucho antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped at 145 seconds, long before reaching orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"part":"fairingA","name":{"es":"Cofia, primera mitad","en":"Nose fairing, first half"},"fate":{"es":"Se soltó junto con la otra mitad a los 203 segundos, antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped together with the other half at 203 seconds, before reaching orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"part":"fairingB","name":{"es":"Cofia, segunda mitad","en":"Nose fairing, second half"},"fate":{"es":"Se soltó junto con la otra mitad a los 203 segundos, antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped together with the other half at 203 seconds, before reaching orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"part":"stage1","name":{"es":"Atlas (etapa central con el motor sustentador)","en":"Atlas (core stage with the sustainer engine)"},"fate":{"es":"Se apagó cuando iba a unos 12.540 km/h, se separó a los 241 segundos y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It shut down while going about 12,540 km/h, separated at 241 seconds and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"part":"interstage","name":{"es":"Adaptador entre etapas","en":"Interstage adapter"},"fate":{"es":"Quedó unido al Atlas cuando una carga explosiva lo cortó cerca de su borde de arriba, y volvió a caer con él a la Tierra; no encontramos en qué lugar.","en":"It stayed attached to the Atlas when an explosive charge cut it near its top edge, and fell back to Earth with it; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"},{"part":"stage2","name":{"es":"Centaur (segunda etapa)","en":"Centaur (second stage)"},"fate":{"es":"Después de soltar a Surveyor 1 giró y vació sus tanques para no chocar con la Luna, y quedó en una órbita muy alargada alrededor de la Tierra, de 12,4 días por vuelta; no encontramos qué fue de él después.","en":"After releasing Surveyor 1 it turned around and emptied its tanks so it would not hit the Moon, and it was left in a very stretched orbit around Earth, 12.4 days per lap; we could not find what became of it afterward."},"where":"earthOrbit","src":"https://ntrs.nasa.gov/api/citations/19680014866/downloads/19680014866.pdf"}],"left":[{"name":{"es":"Radar de marcación de altitud","en":"Altitude marking radar"},"fate":{"es":"Iba en la tobera del retrocohete principal, avisó que la Luna estaba cerca y estaba hecho para salir despedido cuando ese motor se encendía; siguió cayendo hacia la Luna y no encontramos dónde chocó.","en":"It sat in the nozzle of the main retro-rocket, signaled that the Moon was near and was built to be blown out when that motor fired; it kept falling toward the Moon and we could not find where it hit."},"where":"moonImpact","src":"https://ntrs.nasa.gov/api/citations/19660022877/downloads/19660022877.pdf"},{"name":{"es":"Carcasa del retrocohete principal","en":"Main retro-rocket case"},"fate":{"es":"Frenó a Surveyor 1 durante unos 40 segundos y, ya vacía, fue expulsada a 31.000 pies de altura (unos 9,4 km); siguió cayendo hacia la Luna y no encontramos dónde chocó.","en":"It slowed Surveyor 1 for about 40 seconds and, once empty, was ejected 31,000 feet up (about 9.4 km); it kept falling toward the Moon and we could not find where it hit."},"where":"moonImpact","src":"https://www.jpl.nasa.gov/news/surveyor-i-mission/"}]},"pioneer10":{"rocket":"atlasCentaurTE","site":"cape","pad":"LC-36A","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"El Atlas-Centaur AC-27 espera en la plataforma 36A de Cabo Kennedy (hoy Cabo Cañaveral). Sobre el Centaur lleva algo que se usa por primera vez: una tercera etapa de combustible sólido. Encima viaja la Pioneer 10.","en":"Atlas-Centaur AC-27 waits on pad 36A at Cape Kennedy (now Cape Canaveral). On top of the Centaur it carries something used for the first time: a solid-fuel third stage. Pioneer 10 rides above it."},"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"id":"liftoff","t":0,"title":{"es":"Despegue rumbo a Júpiter","en":"Liftoff for Jupiter"},"text":{"es":"3 de marzo de 1972, 01:49 (hora universal), al cuarto intento: tres cuentas regresivas anteriores se suspendieron. Empujan los tres motores grandes del Atlas: dos impulsores y uno central, el sustentador.","en":"3 March 1972, 01:49 (Universal Time), on the fourth try: three earlier countdowns were called off. The three big Atlas engines do the pushing: two boosters and one in the middle, the sustainer."},"ignite":["boosterSection","stage1"],"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"id":"boosterSection","t":152.12,"title":{"es":"Se sueltan dos motores","en":"Two engines drop away"},"text":{"es":"A los 149 segundos se apagan los dos motores impulsores y 3 segundos después se sueltan con su sección. A los 194 se van los paneles aislantes del Centaur. Todo vuelve a caer a la Tierra; no encontramos en qué lugar.","en":"At 149 seconds the two booster engines shut down, and 3 seconds later they drop away with their section. At 194 the Centaur's insulation panels go too. It all falls back to Earth; we could not find where."},"drop":["boosterSection"],"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"id":"stage1","t":245.82,"title":{"es":"Adiós al Atlas","en":"Goodbye to the Atlas"},"text":{"es":"A los 243 segundos se apaga el motor central y, casi 3 segundos después, el Atlas se separa junto con el adaptador entre etapas. Vuelve a caer a la Tierra; no encontramos en qué lugar.","en":"At 243 seconds the middle engine shuts down and, almost 3 seconds later, the Atlas separates together with the interstage adapter. It falls back to Earth; we could not find where."},"drop":["stage1","interstage"],"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"id":"stage2Start","t":256.22,"title":{"es":"Se enciende el Centaur","en":"The Centaur lights up"},"text":{"es":"A los 256 segundos arrancan los dos motores RL-10 del Centaur, que queman hidrógeno y oxígeno líquidos. Van a empujar durante casi siete minutos y medio.","en":"At 256 seconds the Centaur's two RL-10 engines start, burning liquid hydrogen and liquid oxygen. They will push for almost seven and a half minutes."},"ignite":["stage2"],"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"id":"fairing","t":267.12,"title":{"es":"Fuera la cofia","en":"Nose fairing off"},"text":{"es":"Once segundos después, ya fuera de la atmósfera, la cofia de fibra de vidrio que protegía a la Pioneer se suelta en dos mitades. Vuelven a caer a la Tierra; no encontramos en qué lugar.","en":"Eleven seconds later, already out of the atmosphere, the fiberglass fairing that protected Pioneer comes off in two halves. They fall back to Earth; we could not find where."},"drop":["fairingA","fairingB"],"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"id":"stage2","t":777.31,"title":{"es":"El Centaur se despide","en":"The Centaur lets go"},"text":{"es":"A los 705 segundos el Centaur se apaga. Unos cohetes chicos hacen girar la tercera etapa a unas 60 vueltas por minuto y, a los 777 segundos, el Centaur la suelta. Él quedó en una órbita alargada alrededor de la Tierra.","en":"At 705 seconds the Centaur shuts down. Small rockets spin the third stage to about 60 turns per minute and, at 777 seconds, the Centaur lets it go. The Centaur was left in a stretched orbit around Earth."},"drop":["stage2"],"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"id":"stage3Burn","t":790.72,"title":{"es":"El último empujón","en":"The last push"},"text":{"es":"A los 791 segundos se enciende la tercera etapa y quema su combustible sólido en unos 43 segundos. Deja a la Pioneer 10 a unos 51.800 km/h, más rápido que cualquier nave anterior.","en":"At 791 seconds the third stage ignites and burns its solid fuel in about 43 seconds. It leaves Pioneer 10 going about 51,800 km/h, faster than any spacecraft before it."},"ignite":["stage3"],"speed_kmh":51800,"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"id":"separation","t":935.42,"title":{"es":"Pioneer 10 vuela sola","en":"Pioneer 10 flies alone"},"text":{"es":"A los 935 segundos la Pioneer 10 se separa. La tercera etapa, ya vacía, sale de la Tierra por el mismo camino de escape que la nave. No encontramos ningún informe de la NASA que diga dónde terminó.","en":"At 935 seconds Pioneer 10 separates. The empty third stage leaves Earth on the same escape path as the spacecraft. We could not find any NASA report that says where it ended up."},"drop":["stage3"],"src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"}],"fates":[{"part":"boosterSection","name":{"es":"Sección de impulsores del Atlas (dos motores)","en":"Atlas booster section (two engines)"},"fate":{"es":"Se soltó a los 152 segundos, mucho antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped at 152 seconds, long before reaching orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"part":"stage1","name":{"es":"Atlas (etapa central con el motor sustentador)","en":"Atlas (core stage with the sustainer engine)"},"fate":{"es":"Se separó a los 246 segundos, antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It separated at 246 seconds, before reaching orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"part":"interstage","name":{"es":"Adaptador entre etapas","en":"Interstage adapter"},"fate":{"es":"Formaba parte de la primera etapa, se fue con el Atlas y volvió a caer con él a la Tierra; no encontramos en qué lugar.","en":"It was part of the first stage, left with the Atlas and fell back to Earth with it; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"part":"fairingA","name":{"es":"Cofia, primera mitad","en":"Nose fairing, first half"},"fate":{"es":"Se soltó con pernos explosivos y resortes a los 267 segundos, junto con la otra mitad, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was released by explosive bolts and springs at 267 seconds, together with the other half, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"part":"fairingB","name":{"es":"Cofia, segunda mitad","en":"Nose fairing, second half"},"fate":{"es":"Se soltó con pernos explosivos y resortes a los 267 segundos, junto con la otra mitad, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was released by explosive bolts and springs at 267 seconds, together with the other half, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"part":"stage2","name":{"es":"Centaur (segunda etapa)","en":"Centaur (second stage)"},"fate":{"es":"No salió de la Tierra: después de soltar la tercera etapa frenó para apartarse, y el rastreo lo encontró en una órbita alargada alrededor de la Tierra; no encontramos qué fue de él después.","en":"It did not leave Earth: after releasing the third stage it braked to back away, and tracking found it in a stretched orbit around Earth; we could not find what became of it afterward."},"where":"earthOrbit","src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"},{"part":"stage3","name":{"es":"Tercera etapa (motor sólido TE-M-364-4)","en":"Third stage (TE-M-364-4 solid motor)"},"fate":{"es":"El rastreo mostró que salió de la Tierra por el mismo camino de escape que la Pioneer 10; no encontramos ningún informe de la NASA que diga dónde terminó.","en":"Tracking showed it left Earth on the same escape path as Pioneer 10; we could not find any NASA report that says where it ended up."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19730011461/downloads/19730011461.pdf"}],"left":[]},"pioneer11":{"rocket":"atlasCentaurTE","site":"cape","pad":"LC-36B","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"El Atlas-Centaur AC-30 espera en la plataforma 36B de Cabo Kennedy (hoy Cabo Cañaveral). Su Centaur es del nuevo modelo D-1A, guiado por una computadora digital. Arriba van la tercera etapa sólida y la Pioneer 11.","en":"Atlas-Centaur AC-30 waits on pad 36B at Cape Kennedy (now Cape Canaveral). Its Centaur is the new D-1A model, guided by a digital computer. On top sit the solid-fuel third stage and Pioneer 11."},"src":"https://ntrs.nasa.gov/api/citations/19730017158/downloads/19730017158.pdf"},{"id":"liftoff","t":0,"title":{"es":"Despegue rumbo a Júpiter","en":"Liftoff for Jupiter"},"text":{"es":"6 de abril de 1973, 02:11 (hora universal). Después de una cuenta regresiva sin problemas, el Atlas despega a la hora prevista. Empujan sus dos motores impulsores y el sustentador.","en":"6 April 1973, 02:11 (Universal Time). After a smooth countdown the Atlas lifts off at the planned time. Its two booster engines and its sustainer engine do the pushing."},"ignite":["boosterSection","stage1"],"src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"id":"boosterSection","t":143.5,"title":{"es":"Se sueltan dos motores","en":"Two engines drop away"},"text":{"es":"A los 140 segundos se apagan los dos motores impulsores y 3 segundos después se sueltan con su sección. A los 186 se van los paneles aislantes del Centaur. Todo vuelve a caer a la Tierra; no encontramos en qué lugar.","en":"At 140 seconds the two booster engines shut down, and 3 seconds later they drop away with their section. At 186 the Centaur's insulation panels go too. It all falls back to Earth; we could not find where."},"drop":["boosterSection"],"src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"id":"stage1","t":247.6,"title":{"es":"Adiós al Atlas","en":"Goodbye to the Atlas"},"text":{"es":"A los 244 segundos se apaga el motor central y, unos 3 segundos después, el Atlas se separa junto con el adaptador entre etapas. Vuelve a caer a la Tierra; no encontramos en qué lugar.","en":"At 244 seconds the middle engine shuts down and, about 3 seconds later, the Atlas separates together with the interstage adapter. It falls back to Earth; we could not find where."},"drop":["stage1","interstage"],"src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"id":"stage2Start","t":257.2,"title":{"es":"Se enciende el Centaur","en":"The Centaur lights up"},"text":{"es":"A los 257 segundos arrancan los motores del Centaur, que queman hidrógeno y oxígeno líquidos. Van a empujar durante casi siete minutos y medio.","en":"At 257 seconds the Centaur's engines start, burning liquid hydrogen and liquid oxygen. They will push for almost seven and a half minutes."},"ignite":["stage2"],"src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"id":"fairing","t":270.5,"title":{"es":"Fuera la cofia","en":"Nose fairing off"},"text":{"es":"Unos 13 segundos después se suelta la cofia que protegía a la Pioneer durante el paso por la atmósfera. Sus dos mitades vuelven a caer a la Tierra; no encontramos en qué lugar.","en":"About 13 seconds later the fairing that protected Pioneer on its way through the atmosphere is released. Its two halves fall back to Earth; we could not find where."},"drop":["fairingA","fairingB"],"src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"id":"stage2","t":777.6,"title":{"es":"El Centaur se despide","en":"The Centaur lets go"},"text":{"es":"A los 705 segundos el Centaur se apaga. La tercera etapa empieza a girar como un trompo y, a los 778 segundos, el Centaur la suelta y se aparta soltando helio. Quedó en una órbita alargada alrededor de la Tierra.","en":"At 705 seconds the Centaur shuts down. The third stage starts spinning like a top and, at 778 seconds, the Centaur lets it go and backs away by venting helium. It was left in a stretched orbit around Earth."},"drop":["stage2"],"src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"id":"stage3Burn","t":791.0,"title":{"es":"El último empujón","en":"The last push"},"text":{"es":"A los 791 segundos se enciende la tercera etapa y quema su combustible sólido en unos 43 segundos. La Pioneer 11 alcanza unos 51.800 km/h, tan veloz como la Pioneer 10.","en":"At 791 seconds the third stage ignites and burns its solid fuel in about 43 seconds. Pioneer 11 reaches about 51,800 km/h, as fast as Pioneer 10."},"ignite":["stage3"],"speed_kmh":51800,"src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"id":"separation","t":934.9,"title":{"es":"Pioneer 11 vuela sola","en":"Pioneer 11 flies alone"},"text":{"es":"A los 935 segundos la Pioneer 11 se separa. La tercera etapa, ya vacía, sale de la Tierra por el mismo camino de escape que la nave. No encontramos ningún informe de la NASA que diga dónde terminó.","en":"At 935 seconds Pioneer 11 separates. The empty third stage leaves Earth on the same escape path as the spacecraft. We could not find any NASA report that says where it ended up."},"drop":["stage3"],"src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"}],"fates":[{"part":"boosterSection","name":{"es":"Sección de impulsores del Atlas (dos motores)","en":"Atlas booster section (two engines)"},"fate":{"es":"Se soltó a los 143,5 segundos, mucho antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped at 143.5 seconds, long before reaching orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"part":"stage1","name":{"es":"Atlas (etapa central con el motor sustentador)","en":"Atlas (core stage with the sustainer engine)"},"fate":{"es":"Se separó a los 248 segundos, antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It separated at 248 seconds, before reaching orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"part":"interstage","name":{"es":"Adaptador entre etapas","en":"Interstage adapter"},"fate":{"es":"Según el plan de vuelo se quedó con el Atlas cuando una carga explosiva separó al Centaur, y volvió a caer con él a la Tierra; no encontramos en qué lugar.","en":"According to the flight plan it stayed with the Atlas when an explosive charge separated the Centaur, and fell back to Earth with it; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19730017158/downloads/19730017158.pdf"},{"part":"fairingA","name":{"es":"Cofia, primera mitad","en":"Nose fairing, first half"},"fate":{"es":"Se soltó junto con la otra mitad a los 270,5 segundos, poco después de encenderse el Centaur, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped together with the other half at 270.5 seconds, shortly after the Centaur started, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"part":"fairingB","name":{"es":"Cofia, segunda mitad","en":"Nose fairing, second half"},"fate":{"es":"Se soltó junto con la otra mitad a los 270,5 segundos, poco después de encenderse el Centaur, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped together with the other half at 270.5 seconds, shortly after the Centaur started, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"part":"stage2","name":{"es":"Centaur (segunda etapa)","en":"Centaur (second stage)"},"fate":{"es":"No salió de la Tierra: se apartó de la tercera etapa soltando helio y, como estaba previsto, quedó en una órbita alargada alrededor de la Tierra, donde el rastreo lo encontró; no encontramos qué fue de él después.","en":"It did not leave Earth: it backed away from the third stage by venting helium and, as planned, stayed in a stretched orbit around Earth, where tracking found it; we could not find what became of it afterward."},"where":"earthOrbit","src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"},{"part":"stage3","name":{"es":"Tercera etapa (motor sólido TE-M-364-4)","en":"Third stage (TE-M-364-4 solid motor)"},"fate":{"es":"El rastreo mostró que salió de la Tierra por el mismo camino de escape que la Pioneer 11; no encontramos ningún informe de la NASA que diga dónde terminó.","en":"Tracking showed it left Earth on the same escape path as Pioneer 11; we could not find any NASA report that says where it ended up."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19750013263/downloads/19750013263.pdf"}],"left":[]},"apollo11":{"rocket":"saturnV","site":"cape","pad":"LC-39A","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma 39A","en":"On Pad 39A"},"text":{"es":"El Saturno V espera en la plataforma 39A del Centro Espacial Kennedy. En la punta van tres astronautas, la nave Columbia y el módulo lunar Eagle.","en":"The Saturn V waits on Pad 39A at Kennedy Space Center. At the top ride three astronauts, the spacecraft Columbia and the lunar module Eagle."},"src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11a_Summary.htm"},{"id":"liftoff","t":0,"title":{"es":"Despegue hacia la Luna","en":"Liftoff for the Moon"},"text":{"es":"El 16 de julio de 1969, a las 13:32 (hora universal), los motores de la primera etapa levantan el cohete de la plataforma.","en":"On 16 July 1969 at 13:32 (Universal Time), the first stage engines lift the rocket off the pad."},"ignite":["stage1"],"src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11i_Timeline.htm"},{"id":"stage1","t":162.3,"title":{"es":"Se suelta la primera etapa","en":"First stage drops away"},"text":{"es":"A los 2 minutos y 42 segundos, a 67 km de altura, la primera etapa ya vacía se suelta y cae al océano Atlántico, a unos 661 km del lugar de lanzamiento. Se enciende la segunda etapa.","en":"At 2 minutes 42 seconds, 67 km up, the empty first stage drops away and falls into the Atlantic Ocean, about 661 km from the launch site. The second stage lights up."},"drop":["stage1"],"ignite":["stage2"],"alt_km":66.7,"speed_kmh":9986,"src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11d_Ascent_Phase.htm"},{"id":"interstage","t":192.3,"title":{"es":"Se suelta el anillo","en":"The ring drops away"},"text":{"es":"Treinta segundos después se suelta el anillo que unía las dos primeras etapas. El cohete aún no iba tan rápido como para quedar en órbita, así que el anillo volvió a caer. No encontramos en qué lugar.","en":"Thirty seconds later the ring that joined the first two stages drops away. The rocket was still too slow to stay in orbit, so the ring fell back. We could not find where."},"drop":["interstage"],"src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11i_Timeline.htm"},{"id":"les","t":197.9,"title":{"es":"Se suelta la torre","en":"Escape tower drops away"},"text":{"es":"A los 3 minutos y 18 segundos se suelta la torre de escape: un cohete en la punta para alejar la cápsula si algo fallaba al despegar. No hizo falta usarla. Volvió a caer; no encontramos en qué lugar.","en":"At 3 minutes 18 seconds the escape tower drops away: a rocket on the tip to pull the capsule clear if the launch went wrong. It was not needed. It fell back; we could not find where."},"drop":["les"],"src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11i_Timeline.htm"},{"id":"stage2","t":549.0,"title":{"es":"Se suelta la segunda etapa","en":"Second stage drops away"},"text":{"es":"A los 9 minutos y 9 segundos, a 187 km de altura, la segunda etapa se suelta y cae al océano Atlántico, a casi 4.400 km del lugar de lanzamiento. Se enciende la tercera etapa.","en":"At 9 minutes 9 seconds, 187 km up, the second stage drops away and falls into the Atlantic Ocean, almost 4,400 km from the launch site. The third stage lights up."},"drop":["stage2"],"ignite":["stage3"],"alt_km":187.4,"speed_kmh":24908,"src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11d_Ascent_Phase.htm"},{"id":"orbit","t":709.33,"title":{"es":"En órbita terrestre","en":"In Earth orbit"},"text":{"es":"A los 11 minutos y 49 segundos la nave ya gira alrededor de la Tierra a unos 28.000 km/h, con la tercera etapa todavía unida. Da una vuelta y media mientras se revisan los sistemas.","en":"At 11 minutes 49 seconds the spacecraft is circling Earth at about 28,000 km/h, with the third stage still attached. It goes around one and a half times while the systems are checked."},"alt_km":191.1,"speed_kmh":28055,"src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11d_Ascent_Phase.htm"},{"id":"tli","t":9856.2,"title":{"es":"Rumbo a la Luna","en":"Off to the Moon"},"text":{"es":"A las 2 horas y 44 minutos la tercera etapa se vuelve a encender durante casi 6 minutos. La nave sale de la órbita de la Tierra a unos 39.000 km/h, camino a la Luna.","en":"At 2 hours 44 minutes the third stage fires again for almost 6 minutes. The spacecraft leaves Earth orbit at about 39,000 km/h, on its way to the Moon."},"ignite":["stage3"],"src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11a_Summary.htm"},{"id":"separation","t":15423.0,"title":{"es":"Columbia saca al Eagle","en":"Columbia pulls Eagle out"},"text":{"es":"Columbia se separa, se da vuelta y se engancha al módulo lunar Eagle. A las 4 horas y 17 minutos lo saca de la tercera etapa. La etapa vacía pasó de largo junto a la Luna y quedó girando alrededor del Sol.","en":"Columbia separates, turns around and docks with the lunar module Eagle. At 4 hours 17 minutes it pulls Eagle out of the third stage. The empty stage flew past the Moon and ended up orbiting the Sun."},"drop":["stage3"],"src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11a_Summary.htm"}],"fates":[{"part":"stage1","name":{"es":"Primera etapa (S-IC)","en":"First stage (S-IC)"},"fate":{"es":"Cayó al océano Atlántico unos 9 minutos después del despegue, a unos 661 km del lugar de lanzamiento, según el punto de caída que calculó la NASA.","en":"It fell into the Atlantic Ocean about 9 minutes after liftoff, about 661 km from the launch site, according to the impact point NASA calculated."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11a_Summary.htm"},{"part":"interstage","name":{"es":"Anillo entre etapas","en":"Interstage ring"},"fate":{"es":"Se soltó a los 3 minutos y 12 segundos, mucho antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped at 3 minutes 12 seconds, long before orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11i_Timeline.htm"},{"part":"les","name":{"es":"Torre de escape","en":"Launch escape tower"},"fate":{"es":"Se soltó sin usarse a los 3 minutos y 18 segundos, mucho antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped unused at 3 minutes 18 seconds, long before orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11i_Timeline.htm"},{"part":"stage2","name":{"es":"Segunda etapa (S-II)","en":"Second stage (S-II)"},"fate":{"es":"Cayó al océano Atlántico unos 20 minutos después del despegue, a casi 4.400 km del lugar de lanzamiento, según el punto de caída que calculó la NASA.","en":"It fell into the Atlantic Ocean about 20 minutes after liftoff, almost 4,400 km from the launch site, according to the impact point NASA calculated."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11a_Summary.htm"},{"part":"stage3","name":{"es":"Tercera etapa (S-IVB)","en":"Third stage (S-IVB)"},"fate":{"es":"Después de dejar a Columbia y Eagle camino a la Luna, pasó a unos 3.380 km de la superficie lunar el 19 de julio de 1969 y quedó en órbita alrededor del Sol, con una vuelta cada 342 días.","en":"After sending Columbia and Eagle on their way, it passed about 3,380 km from the Moon's surface on 19 July 1969 and went into orbit around the Sun, with one lap every 342 days."},"where":"sunOrbit","src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11a_Summary.htm"}],"left":[{"name":{"es":"Etapa de descenso del Eagle","en":"Eagle descent stage"},"fate":{"es":"Sirvió de plataforma de despegue para la parte de arriba del Eagle y se quedó en la Luna, con una placa conmemorativa detrás de la escalera.","en":"It served as the launch platform for the upper part of Eagle and stayed on the Moon, with a commemorative plaque behind its ladder."},"where":"onMoon","src":"https://nssdc.gsfc.nasa.gov/nmc/spacecraft/display.action?id=1969-059C"},{"name":{"es":"Etapa de ascenso del Eagle","en":"Eagle ascent stage"},"fate":{"es":"Llevó a Armstrong y Aldrin de vuelta al Columbia y se soltó en órbita alrededor de la Luna; no se sabe dónde terminó.","en":"It carried Armstrong and Aldrin back to Columbia and was cast off in orbit around the Moon; it is not known where it ended up."},"where":"unknown","src":"https://nssdc.gsfc.nasa.gov/nmc/spacecraft/display.action?id=1969-059C"},{"name":{"es":"Reflector láser","en":"Laser ranging retroreflector"},"fate":{"es":"Quedó en la superficie para devolver hacia la Tierra los rayos láser con los que se mide la distancia entre la Tierra y la Luna.","en":"It was left on the surface to bounce back the laser beams from Earth that are used to measure the distance between Earth and the Moon."},"where":"onMoon","src":"https://nssdc.gsfc.nasa.gov/nmc/experiment/display.action?id=1969-059C-04"},{"name":{"es":"Sismómetro","en":"Seismometer"},"fate":{"es":"Los astronautas lo instalaron al sur del Eagle para medir los temblores de la Luna, y llegó a registrar sus propios pasos sobre la superficie.","en":"The astronauts set it up south of Eagle to measure moonquakes, and it even recorded their own footsteps on the surface."},"where":"onMoon","src":"https://www.nasa.gov/wp-content/uploads/static/history/SP-4029/Apollo_11a_Summary.htm"},{"name":{"es":"Bandera de Estados Unidos","en":"United States flag"},"fate":{"es":"Armstrong y Aldrin la plantaron en un mástil de aluminio y figura en la lista de la NASA de objetos que quedaron en la Luna.","en":"Armstrong and Aldrin put it up on an aluminium staff, and it is on NASA's list of objects left on the Moon."},"where":"onMoon","src":"https://www.nasa.gov/wp-content/uploads/2024/02/final-catalogue-of-manmade-material-on-the-moon.pdf"},{"name":{"es":"Recuerdos y homenajes","en":"Mementos and tributes"},"fate":{"es":"En la lista de la NASA figuran una insignia del Apolo 1, dos medallas en honor a los cosmonautas Gagarin y Komarov, una rama de olivo de oro y un disco conmemorativo.","en":"NASA's list includes an Apollo 1 patch, two medals honouring the cosmonauts Gagarin and Komarov, a gold olive branch and a memorial disc."},"where":"onMoon","src":"https://www.nasa.gov/wp-content/uploads/2024/02/final-catalogue-of-manmade-material-on-the-moon.pdf"},{"name":{"es":"Mochilas, botas y cámara","en":"Backpacks, overshoes and camera"},"fate":{"es":"Antes de despegar de la Luna dejaron en la superficie las mochilas de los trajes, las botas lunares, la cámara de televisión y otros equipos.","en":"Before lifting off from the Moon they left the suit backpacks, the lunar overshoes, the TV camera and other gear on the surface."},"where":"onMoon","src":"https://www.nasa.gov/wp-content/uploads/2024/02/final-catalogue-of-manmade-material-on-the-moon.pdf"}]},"viking1":{"rocket":"titan3e","site":"cape","pad":"LC-41","steps":[{"id":"pad","t":null,"title":{"es":"En el Complejo 41","en":"On Complex 41"},"text":{"es":"El Titan IIIE-Centaur espera en el Complejo 41 de Cabo Cañaveral. Mide 48,8 metros. Bajo la cofia de la punta van, unidos, el orbitador y el módulo de aterrizaje Viking 1.","en":"The Titan IIIE-Centaur waits on Complex 41 at Cape Canaveral. It is 48.8 metres tall. Under the shroud at the tip ride the Viking 1 orbiter and lander, joined together."},"src":"https://ntrs.nasa.gov/api/citations/19750018961/downloads/19750018961.pdf"},{"id":"liftoff","t":0,"title":{"es":"Despegue con motores sólidos","en":"Liftoff on solid motors"},"text":{"es":"El 20 de agosto de 1975, a las 21:22 (hora universal), se encienden los dos motores de combustible sólido de los costados. Ellos solos levantan el cohete: el motor del centro sigue apagado.","en":"On 20 August 1975 at 21:22 (Universal Time), the two solid rocket motors on the sides ignite. They lift the rocket alone: the engine in the middle is still off."},"ignite":["srbGround"],"src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"id":"stage1Ignition","t":110.4,"title":{"es":"Encendido en pleno vuelo","en":"Engine start in flight"},"text":{"es":"A los 110 segundos, cuando los motores sólidos se están quedando sin combustible, se enciende en pleno vuelo el motor de la primera etapa central, que quema combustible líquido.","en":"At 110 seconds, as the solid motors are running out of propellant, the engine of the first core stage, which burns liquid propellants, starts up in mid-flight."},"ignite":["stage1"],"src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"id":"srbGround","t":121.7,"title":{"es":"Se sueltan los motores sólidos","en":"Solid motors drop away"},"text":{"es":"A los 122 segundos los dos motores sólidos, ya vacíos, se sueltan. El cohete aún no iba tan rápido como para quedar en órbita, así que volvieron a caer. No encontramos en qué lugar.","en":"At 122 seconds the two empty solid motors drop away. The rocket was still too slow to stay in orbit, so they fell back. We could not find where."},"drop":["srbGround"],"src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"id":"stage1","t":260.1,"title":{"es":"Se suelta la primera etapa","en":"First stage drops away"},"text":{"es":"A los 4 minutos y 20 segundos la primera etapa central se queda sin combustible y se suelta, y en el mismo instante se enciende la segunda. La primera volvió a caer; no encontramos en qué lugar.","en":"At 4 minutes 20 seconds the first core stage runs out of propellant and drops away, and at the same instant the second one lights up. The first fell back; we could not find where."},"drop":["stage1"],"ignite":["stage2"],"src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"id":"fairing","t":270.3,"title":{"es":"Se abre la cofia","en":"The shroud opens"},"text":{"es":"Diez segundos después la cofia que protegía a la nave se parte en dos mitades y se suelta. También volvió a caer; no encontramos en qué lugar.","en":"Ten seconds later the shroud that protected the spacecraft splits into two halves and drops away. It fell back too; we could not find where."},"drop":["fairingA","fairingB"],"src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"id":"stage2","t":473.8,"title":{"es":"Turno del Centaur","en":"Centaur takes over"},"text":{"es":"A los 7 minutos y 54 segundos se suelta la segunda etapa, que vuelve a caer (no encontramos en qué lugar). Se enciende el Centaur y dos minutos después la nave está en órbita, a unos 165 km de altura.","en":"At 7 minutes 54 seconds the second stage drops away and falls back (we could not find where). The Centaur lights up and two minutes later the spacecraft is in orbit, about 165 km up."},"drop":["stage2"],"ignite":["stage3"],"src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"id":"tmi","t":1530.1,"title":{"es":"Rumbo a Marte","en":"Off to Mars"},"text":{"es":"Después de 15 minutos girando alrededor de la Tierra, el Centaur se vuelve a encender durante algo más de 5 minutos y pone a Viking 1 en camino a Marte.","en":"After 15 minutes circling Earth, the Centaur fires again for a little over 5 minutes and puts Viking 1 on its way to Mars."},"ignite":["stage3"],"src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"id":"separation","t":2066.1,"title":{"es":"Viking 1 viaja sola","en":"Viking 1 flies alone"},"text":{"es":"A los 34 minutos Viking 1 se separa del Centaur y abre sus paneles solares. Después el Centaur hace una última maniobra para no chocar con Marte. Como ya había escapado de la Tierra, quedó girando alrededor del Sol.","en":"At 34 minutes Viking 1 separates from the Centaur and opens its solar panels. Then the Centaur makes one last manoeuvre to miss Mars. As it had already escaped from Earth, it was left orbiting the Sun."},"drop":["stage3"],"src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"}],"fates":[{"part":"srbGround","name":{"es":"Motores de combustible sólido (etapa 0)","en":"Solid rocket motors (stage 0)"},"fate":{"es":"Se soltaron a los 122 segundos, mucho antes de llegar a la órbita, y volvieron a caer a la Tierra; no encontramos en qué lugar.","en":"They were dropped at 122 seconds, long before orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"part":"stage1","name":{"es":"Primera etapa central del Titan","en":"Titan first core stage"},"fate":{"es":"Se soltó a los 4 minutos y 20 segundos, antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped at 4 minutes 20 seconds, before orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"part":"fairingA","name":{"es":"Cofia, primera mitad","en":"Shroud, first half"},"fate":{"es":"Se soltó junto con la otra mitad a los 4 minutos y 30 segundos, antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped together with the other half at 4 minutes 30 seconds, before orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"part":"fairingB","name":{"es":"Cofia, segunda mitad","en":"Shroud, second half"},"fate":{"es":"Se soltó junto con la otra mitad a los 4 minutos y 30 segundos, antes de llegar a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped together with the other half at 4 minutes 30 seconds, before orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"part":"stage2","name":{"es":"Segunda etapa central del Titan","en":"Titan second core stage"},"fate":{"es":"Se soltó a los 7 minutos y 54 segundos, antes de que el Centaur llevara la nave a la órbita, y volvió a caer a la Tierra; no encontramos en qué lugar.","en":"It was dropped at 7 minutes 54 seconds, before the Centaur took the spacecraft to orbit, and fell back to Earth; we could not find where."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"},{"part":"stage3","name":{"es":"Etapa superior Centaur D-1T","en":"Centaur D-1T upper stage"},"fate":{"es":"Después de soltar a Viking 1 hizo una maniobra para no chocar con Marte y, como ya había escapado de la Tierra, quedó en órbita alrededor del Sol.","en":"After releasing Viking 1 it made a manoeuvre to miss Mars and, as it had already escaped from Earth, it was left in orbit around the Sun."},"where":"sunOrbit","src":"https://ntrs.nasa.gov/api/citations/19760021170/downloads/19760021170.pdf"}],"left":[{"name":{"es":"Orbitador Viking 1","en":"Viking 1 Orbiter"},"fate":{"es":"Estudió Marte desde su órbita hasta agosto de 1980, después de más de 1.400 vueltas, y quedó en una órbita más alta para que no cayera sobre el planeta antes de 2019; no encontramos si sigue ahí.","en":"It studied Mars from orbit until August 1980, after more than 1,400 orbits, and was left in a higher orbit so that it would not fall onto the planet before 2019; we could not find whether it is still there."},"where":"unknown","src":"https://nssdc.gsfc.nasa.gov/nmc/spacecraft/display.action?id=1975-075A"},{"name":{"es":"Tapa del bioescudo","en":"Bioshield cap"},"fate":{"es":"Era una de las dos mitades de la cápsula blanca que mantenía sin microbios al módulo de aterrizaje; se soltó unas 2 horas después del lanzamiento, ya camino a Marte, y no encontramos dónde terminó.","en":"It was one of the two halves of the white cocoon that kept the lander free of microbes; it was released about 2 hours after launch, already on the way to Mars, and we could not find where it ended up."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19770022101/downloads/19770022101.pdf"},{"name":{"es":"Base del bioescudo","en":"Bioshield base"},"fate":{"es":"Era la otra mitad de la cápsula blanca; el orbitador la soltó en 1976, poco después de la salida del módulo de aterrizaje, mientras giraba alrededor de Marte, y no encontramos si sigue en órbita.","en":"It was the other half of the white cocoon; the orbiter released it in 1976, shortly after the lander left, while circling Mars, and we could not find whether it is still in orbit."},"where":"unknown","src":"https://ntrs.nasa.gov/api/citations/19780024194/downloads/19780024194.pdf"},{"name":{"es":"Escudo térmico (aeroshell)","en":"Heat shield (aeroshell)"},"fate":{"es":"Frenó la cápsula al entrar en la atmósfera de Marte, se soltó 7 segundos después de abrirse el paracaídas, a unos 6 km de altura, y cayó a la superficie; en 2006 la sonda MRO fotografió el lugar donde probablemente está.","en":"It slowed the capsule as it entered the atmosphere of Mars, was released 7 seconds after the parachute opened, about 6 km up, and fell to the surface; in 2006 the MRO orbiter photographed the place where it probably lies."},"where":"onMars","src":"https://science.nasa.gov/photojournal/viking-lander-1-thomas-a-mutch-memorial-station-imaged-from-orbit"},{"name":{"es":"Cubierta trasera y paracaídas","en":"Base cover and parachute"},"fate":{"es":"El paracaídas de 16 metros frenó la bajada y se soltó junto con la cubierta trasera a cerca de 1,5 km del suelo, al encenderse los motores de aterrizaje; quedaron en Marte y en 2006 la sonda MRO fotografió el lugar donde probablemente están.","en":"The 16 metre parachute slowed the descent and was released with the base cover about 1.5 km above the ground, when the landing engines lit; they stayed on Mars and in 2006 the MRO orbiter photographed the place where they probably lie."},"where":"onMars","src":"https://science.nasa.gov/photojournal/viking-lander-1-thomas-a-mutch-memorial-station-imaged-from-orbit"}]},"pathfinder":{"rocket":"delta7925","site":"cape","pad":"LC-17B","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"Mars Pathfinder espera en la punta de un cohete Delta II 7925 en Cabo Cañaveral. La primera etapa lleva nueve propulsores: seis se encienden al despegar y tres en pleno vuelo.","en":"Mars Pathfinder waits on top of a Delta II 7925 rocket at Cape Canaveral. The first stage carries nine solid boosters: six light at liftoff and three light in flight."},"src":"https://www.jpl.nasa.gov/news/press_kits/m96pkt.pdf"},{"id":"liftoff","t":0,"title":{"es":"Despegue de madrugada","en":"Liftoff before dawn"},"text":{"es":"El 4 de diciembre de 1996, a la 1:58 de la madrugada de Florida, el Delta II despega de Cabo Cañaveral con Pathfinder en la punta.","en":"On December 4, 1996, at 1:58 in the morning in Florida, the Delta II lifts off from Cape Canaveral with Pathfinder on top."},"ignite":["stage1","srbGround"],"src":"https://www.jpl.nasa.gov/news/press_kits/mpfland.pdf"},{"id":"srbGround","t":66,"title":{"es":"Se sueltan seis propulsores","en":"Six boosters drop off"},"text":{"es":"Unos 66 segundos después del despegue, a 18 km de altura, los primeros seis propulsores ya están vacíos y se sueltan. Se encienden los otros tres. En general, en los Delta II estas piezas caen al océano.","en":"About 66 seconds after liftoff, 18 km up, the first six boosters are empty and drop off. The other three light up. In general, on Delta II rockets these pieces fall into the ocean."},"drop":["srbGround"],"ignite":["srbAir"],"alt_km":18.2,"speed_kmh":3690,"src":"https://www.jpl.nasa.gov/news/press_kits/m96pkt.pdf"},{"id":"srbAir","t":131.5,"title":{"es":"Los últimos tres","en":"The last three"},"text":{"es":"A los 2 minutos y 11,5 segundos, a unos 54 km de altura, los tres últimos propulsores ya terminaron su trabajo y se sueltan. En general, en los Delta II también caen al océano.","en":"At 2 minutes 11.5 seconds, about 54 km up, the last three boosters have done their job and drop off. In general, on Delta II rockets they also fall into the ocean."},"drop":["srbAir"],"alt_km":54.3,"speed_kmh":9130,"src":"https://www.jpl.nasa.gov/news/press_kits/m96pkt.pdf"},{"id":"meco","t":260.7,"title":{"es":"Se va la primera etapa","en":"First stage falls away"},"text":{"es":"A los 4 minutos y 21 segundos, a unos 118 km de altura, el motor principal se apaga. La primera etapa se separa y, unos 13 segundos después, se enciende la segunda. En general, la primera etapa cae al océano.","en":"At 4 minutes 21 seconds, about 118 km up, the main engine shuts down. The first stage separates and about 13 seconds later the second stage lights. In general, the first stage falls into the ocean."},"drop":["stage1","interstage"],"ignite":["stage2"],"alt_km":118.3,"speed_kmh":22486,"src":"https://www.jpl.nasa.gov/news/press_kits/m96pkt.pdf"},{"id":"fairing","t":282,"title":{"es":"Se abre la cofia","en":"The nose cone opens"},"text":{"es":"A los 4 minutos y 42 segundos, a 130 km de altura, la cofia que cubría a Pathfinder se desprende. En general, en los Delta II sus dos mitades caen al océano.","en":"At 4 minutes 42 seconds, 130 km up, the nose cone that covered Pathfinder is thrown off. In general, on Delta II rockets its two halves fall into the ocean."},"drop":["fairingA","fairingB"],"alt_km":130.0,"speed_kmh":22583,"src":"https://www.jpl.nasa.gov/news/press_kits/m96pkt.pdf"},{"id":"parking","t":557.9,"title":{"es":"Casi una hora de espera","en":"Nearly an hour's wait"},"text":{"es":"Unos 9 minutos y 20 segundos después del despegue la segunda etapa se apaga, a unos 189 km de altura. Pathfinder gira alrededor de la Tierra casi una hora. Después la etapa se enciende por segunda vez.","en":"About 9 minutes 20 seconds after liftoff the second stage shuts down, about 189 km up. Pathfinder coasts around Earth for nearly an hour. Then the stage fires a second time."},"alt_km":188.7,"speed_kmh":28055,"src":"https://www.jpl.nasa.gov/news/press_kits/m96pkt.pdf"},{"id":"injection","t":4151.8,"title":{"es":"La tercera etapa gira","en":"The third stage spins"},"text":{"es":"Unos cohetes chicos hacen girar la tercera etapa, la PAM-D, a unas 70 vueltas por minuto. Se separa de la segunda, que queda un tiempo en órbita de la Tierra, y se enciende. En el plan, a unos 70 minutos del despegue.","en":"Small rockets spin the third stage, the PAM-D, to about 70 turns per minute. It separates from the second stage, which stays in Earth orbit for a while, and fires. In the plan, about 70 minutes after liftoff."},"drop":["stage2"],"ignite":["stage3"],"src":"https://www.jpl.nasa.gov/news/press_kits/m96pkt.pdf"},{"id":"separation","t":4500,"title":{"es":"Pathfinder sigue por su cuenta","en":"Pathfinder on its own"},"text":{"es":"Un sistema de cables tipo yoyó frena el giro. Unos 75 minutos después del despegue, Pathfinder se separa de la tercera etapa, que queda dando vueltas al Sol.","en":"A yo-yo cable system slows the spin. About 75 minutes after liftoff Pathfinder separates from the third stage, which is left circling the Sun."},"drop":["stage3"],"src":"https://pds.nasa.gov/data/mpfl-m-imp-2-edr-v1.0/mpim_0002/document/mission.htm"}],"fates":[{"part":"srbGround","name":{"es":"Seis propulsores encendidos en tierra","en":"Six ground-lit boosters"},"fate":{"es":"Se soltaron vacíos a los 66 y 67 segundos del despegue; en general, las carcasas de estos propulsores del Delta II caen al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"They dropped away empty 66 and 67 seconds after liftoff; in general, the casings of these Delta II boosters fall into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"srbAir","name":{"es":"Tres propulsores encendidos en vuelo","en":"Three air-lit boosters"},"fate":{"es":"Se soltaron vacíos a los 2 minutos y 11,5 segundos, a unos 54 km de altura; en general, estas carcasas caen al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"They dropped away empty at 2 minutes 11.5 seconds, about 54 km up; in general, these casings fall into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage1","name":{"es":"Primera etapa","en":"First stage"},"fate":{"es":"Llevó el cohete hasta unos 118 km de altura y se separó; en general, la primera etapa del Delta II cae al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"It lifted the rocket to about 118 km and separated; in general, the Delta II first stage falls into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"interstage","name":{"es":"Anillo entre etapas","en":"Interstage ring"},"fate":{"es":"Este anillo une la primera etapa con la segunda; los documentos de la NASA que leímos no dicen qué pasó con él en este vuelo.","en":"This ring joins the first stage to the second; the NASA documents we read do not say what happened to it on this flight."},"where":"unknown","src":"https://www.jpl.nasa.gov/news/press_kits/m96pkt.pdf"},{"part":"fairingA","name":{"es":"Cofia (primera mitad)","en":"Nose cone (first half)"},"fate":{"es":"Se soltó junto con la otra mitad a los 4 minutos y 42 segundos, a 130 km de altura; en general, las mitades de la cofia del Delta II caen al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"It dropped away together with the other half at 4 minutes 42 seconds, 130 km up; in general, the halves of the Delta II nose cone fall into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingB","name":{"es":"Cofia (segunda mitad)","en":"Nose cone (second half)"},"fate":{"es":"Se soltó junto con la primera mitad a los 4 minutos y 42 segundos, a 130 km de altura; en general, las mitades de la cofia del Delta II caen al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"It dropped away together with the first half at 4 minutes 42 seconds, 130 km up; in general, the halves of the Delta II nose cone fall into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage2","name":{"es":"Segunda etapa","en":"Second stage"},"fate":{"es":"Después de su segundo encendido quedó en una órbita alargada alrededor de la Tierra y volvió a caer en la atmósfera el 28 de noviembre de 1997, según el catálogo de satélites de Estados Unidos.","en":"After its second burn it stayed in a stretched orbit around Earth and fell back into the atmosphere on 28 November 1997, according to the U.S. satellite catalog."},"where":"burned","src":"https://celestrak.org/satcat/table-satcat.php?INTDES=1996-068"},{"part":"stage3","name":{"es":"Tercera etapa (PAM-D)","en":"Third stage (PAM-D)"},"fate":{"es":"Después de enviar a Pathfinder hacia Marte también se fue de la Tierra, y el catálogo de satélites de Estados Unidos la registra en órbita alrededor del Sol.","en":"After sending Pathfinder on its way to Mars it left Earth as well, and the U.S. satellite catalog lists it in orbit around the Sun."},"where":"sunOrbit","src":"https://celestrak.org/satcat/table-satcat.php?INTDES=1996-068"}],"left":[{"name":{"es":"Etapa de crucero","en":"Cruise stage"},"fate":{"es":"Esta sección controló la nave durante el viaje a Marte, se soltó antes de entrar en la atmósfera y chocó contra la superficie.","en":"This section controlled the spacecraft during the trip to Mars, was cast off before entering the atmosphere and hit the surface."},"where":"marsImpact","src":"https://pds.nasa.gov/data/mpfl-m-imp-2-edr-v1.0/mpim_0001/document/insthost.htm"},{"name":{"es":"Escudo térmico","en":"Heat shield"},"fate":{"es":"Cayó al suelo durante el descenso, y en una foto tomada desde la órbita en 2006 se ven cuatro manchas que podrían ser pedazos del escudo.","en":"It fell to the ground during the descent, and a photo taken from orbit in 2006 shows four spots that may be pieces of it."},"where":"onMars","src":"https://science.nasa.gov/photojournal/mars-pathfinder-landing-site-and-surroundings"},{"name":{"es":"Cubierta trasera y paracaídas","en":"Back shell and parachute"},"fate":{"es":"La cubierta trasera y el paracaídas quedaron en el suelo al sur del módulo, donde una cámara en órbita los fotografió en 2006.","en":"The back shell and the parachute ended up on the ground south of the lander, where a camera in orbit photographed them in 2006."},"where":"onMars","src":"https://science.nasa.gov/photojournal/mars-pathfinder-landing-site-and-surroundings"},{"name":{"es":"Airbags","en":"Airbags"},"fate":{"es":"Las bolsas de aire que hicieron rebotar a Pathfinder se desinflaron, y en la foto de 2006 tomada desde la órbita todavía se ven partes de ellas junto al módulo.","en":"The airbags that let Pathfinder bounce were deflated, and the 2006 photo taken from orbit still shows parts of them around the lander."},"where":"onMars","src":"https://science.nasa.gov/photojournal/mars-pathfinder-landing-site-and-surroundings"},{"name":{"es":"Rover Sojourner","en":"Sojourner rover"},"fate":{"es":"El pequeño rover bajó por una rampa el 6 de julio de 1997 y trabajó cerca del módulo hasta que se perdió la comunicación el 27 de septiembre de 1997; quedó en Marte.","en":"The small rover rolled down a ramp on 6 July 1997 and worked near the lander until communications were lost on 27 September 1997; it stayed on Mars."},"where":"onMars","src":"https://nssdc.gsfc.nasa.gov/nmc/spacecraft/display.action?id=MESURPR"}]},"spirit":{"rocket":"delta7925","site":"cape","pad":"SLC-17A","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"Spirit espera en la punta de un cohete Delta II de 39,6 metros de alto. Alrededor de la primera etapa hay nueve propulsores: seis se encienden al despegar y tres en pleno vuelo.","en":"Spirit waits on top of a Delta II rocket 39.6 meters tall. Nine solid boosters surround the first stage: six light at liftoff and three light in flight."},"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"liftoff","t":0,"title":{"es":"Despegue hacia Marte","en":"Liftoff for Mars"},"text":{"es":"El 10 de junio de 2003, a las 13:58 de Florida, el Delta II despega con un trueno de Cabo Cañaveral. Empieza un viaje de siete meses hasta Marte.","en":"On June 10, 2003, at 1:58 p.m. in Florida, the Delta II thunders away from Cape Canaveral. A seven-month trip to Mars begins."},"ignite":["stage1","srbGround"],"src":"https://www.jpl.nasa.gov/news/nasas-spirit-rises-on-its-way-to-mars/"},{"id":"srbGround","t":66,"title":{"es":"Se sueltan seis propulsores","en":"Six boosters drop off"},"text":{"es":"A los 66 segundos, a 18 km de altura, los seis propulsores ya están vacíos. Se sueltan de a tres y caen al océano Atlántico. En ese momento se encienden los otros tres.","en":"At 66 seconds, 18 km up, the six boosters are empty. They let go in sets of three and fall into the Atlantic Ocean. Right then the other three light up."},"drop":["srbGround"],"ignite":["srbAir"],"alt_km":18.0,"speed_kmh":3668,"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"srbAir","t":131.5,"title":{"es":"Los últimos tres","en":"The last three"},"text":{"es":"A los 2 minutos y 11,5 segundos, a 52,4 km de altura y a 9.046 km/h, los tres últimos propulsores se sueltan y caen al Atlántico.","en":"At 2 minutes 11.5 seconds, 52.4 km up and flying at 9,046 km/h, the last three boosters drop off and fall into the Atlantic."},"drop":["srbAir"],"alt_km":52.4,"speed_kmh":9046,"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"meco","t":263.4,"title":{"es":"Se va la primera etapa","en":"First stage falls away"},"text":{"es":"A los 4 minutos y 23 segundos, a 119 km de altura, el motor principal se apaga. La primera etapa se separa y cae al Atlántico. Unos 13 segundos después se enciende la segunda etapa.","en":"At 4 minutes 23 seconds, 119 km up, the main engine shuts down. The first stage separates and falls into the Atlantic. About 13 seconds later the second stage lights."},"drop":["stage1","interstage"],"ignite":["stage2"],"alt_km":119.3,"speed_kmh":22317,"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"fairing","t":282,"title":{"es":"Se abre la cofia","en":"The nose cone opens"},"text":{"es":"A los 4 minutos y 42 segundos, a 121 km de altura, la cofia que protegía a Spirit durante la subida se desprende. Sus dos mitades caen al océano Atlántico.","en":"At 4 minutes 42 seconds, 121 km up, the nose cone that shielded Spirit on the way up falls away. Its two halves fall into the Atlantic Ocean."},"drop":["fairingA","fairingB"],"alt_km":121.3,"speed_kmh":22377,"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"parking","t":578.5,"title":{"es":"Una órbita de espera","en":"A waiting orbit"},"text":{"es":"A los 9 minutos y 38 segundos la segunda etapa se apaga. Spirit gira alrededor de la Tierra a unos 170 km de altura y a 28.095 km/h. Antes de dar una vuelta completa, la etapa se enciende otra vez por 2 o 3 minutos.","en":"At 9 minutes 38 seconds the second stage shuts down. Spirit circles Earth about 170 km up at 28,095 km/h. Before finishing one lap, the stage fires again for 2 to 3 minutes."},"alt_km":170.4,"speed_kmh":28095,"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"injection","t":1859.4,"title":{"es":"La tercera etapa gira","en":"The third stage spins"},"text":{"es":"Cohetes chicos hacen girar la tercera etapa a unas 63 vueltas por minuto. Se separa de la segunda, que queda en órbita de la Tierra, y empuja unos 87 segundos. En el plan del primer día posible, eso era a los 31 minutos.","en":"Small rockets spin the third stage to about 63 turns per minute. It leaves the second stage behind in Earth orbit and burns for about 87 seconds. In the plan for the first possible day, that came at 31 minutes."},"drop":["stage2"],"ignite":["stage3"],"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"separation","t":2160,"title":{"es":"Spirit sigue por su cuenta","en":"Spirit on its own"},"text":{"es":"Unas pesas con cables, como yoyós, frenan el giro. Unos 36 minutos después del despegue, sobre el océano Índico, Spirit se separa de la tercera etapa, que queda dando vueltas al Sol.","en":"Weights on cables, like yo-yos, slow the spin. About 36 minutes after liftoff, over the Indian Ocean, Spirit separates from the third stage, which is left circling the Sun."},"drop":["stage3"],"src":"https://www.jpl.nasa.gov/news/nasas-spirit-rises-on-its-way-to-mars/"}],"fates":[{"part":"srbGround","name":{"es":"Seis propulsores encendidos en tierra","en":"Six ground-lit boosters"},"fate":{"es":"Se quedaron sin combustible cerca de un minuto después del despegue, se soltaron de a tres a los 66 y 67 segundos y cayeron al océano Atlántico.","en":"They ran out of fuel about a minute after liftoff, were dropped in sets of three at 66 and 67 seconds and fell into the Atlantic Ocean."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"srbAir","name":{"es":"Tres propulsores encendidos en vuelo","en":"Three air-lit boosters"},"fate":{"es":"Se encendieron en pleno vuelo, se soltaron a los 2 minutos y 11,5 segundos del despegue y cayeron al océano Atlántico.","en":"They lit in flight, were dropped 2 minutes 11.5 seconds after liftoff and fell into the Atlantic Ocean."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage1","name":{"es":"Primera etapa","en":"First stage"},"fate":{"es":"Funcionó unos 4 minutos y 23 segundos, se separó y cayó al océano Atlántico.","en":"It burned for about 4 minutes 23 seconds, separated and fell into the Atlantic Ocean."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"interstage","name":{"es":"Anillo entre etapas","en":"Interstage ring"},"fate":{"es":"Este anillo une la primera etapa con la segunda; los documentos de la NASA que leímos no dicen qué pasó con él en este vuelo.","en":"This ring joins the first stage to the second; the NASA documents we read do not say what happened to it on this flight."},"where":"unknown","src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"part":"fairingA","name":{"es":"Cofia (primera mitad)","en":"Nose cone (first half)"},"fate":{"es":"La cofia que cubría la nave se abrió en dos mitades poco después de apagarse el motor principal, y esta mitad cayó al océano Atlántico.","en":"The nose cone that covered the spacecraft split into two halves soon after the main engine shut down, and this half fell into the Atlantic Ocean."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingB","name":{"es":"Cofia (segunda mitad)","en":"Nose cone (second half)"},"fate":{"es":"Era la segunda mitad de la cofia y cayó al océano Atlántico igual que la primera.","en":"It was the second half of the nose cone and fell into the Atlantic Ocean just like the first."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage2","name":{"es":"Segunda etapa","en":"Second stage"},"fate":{"es":"Después de su segundo encendido quedó en una órbita alargada alrededor de la Tierra y volvió a caer en la atmósfera el 27 de enero de 2004, según el catálogo de satélites de Estados Unidos.","en":"After its second burn it stayed in a stretched orbit around Earth and fell back into the atmosphere on 27 January 2004, according to the U.S. satellite catalog."},"where":"burned","src":"https://celestrak.org/satcat/table-satcat.php?INTDES=2003-027"},{"part":"stage3","name":{"es":"Tercera etapa (Star 48B)","en":"Third stage (Star 48B)"},"fate":{"es":"Después de empujar unos 87 segundos siguió viaje por un camino elegido a propósito para no chocar con Marte, y quedó en órbita alrededor del Sol.","en":"After its 87-second burn it flew on along a path chosen on purpose to miss Mars, and it stayed in orbit around the Sun."},"where":"sunOrbit","src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"}],"left":[{"name":{"es":"Etapa de crucero","en":"Cruise stage"},"fate":{"es":"Dio electricidad y corrigió el rumbo durante el viaje, se soltó 15 minutos antes de entrar en la atmósfera y, según el plan de la misión, terminó chocando contra Marte.","en":"It gave power and steered during the trip, was cast off 15 minutes before entering the atmosphere and, according to the mission plan, ended up hitting Mars."},"where":"marsImpact","src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"name":{"es":"Escudo térmico","en":"Heat shield"},"fate":{"es":"Se soltó durante el descenso, y en una foto tomada desde la órbita en 2006 se lo ve en el borde del cráter Bonneville.","en":"It was dropped during the descent, and a photo taken from orbit in 2006 shows it at the edge of Bonneville crater."},"where":"onMars","src":"https://science.nasa.gov/photojournal/mars-exploration-rover-landing-site-at-gusev-crater/"},{"name":{"es":"Cubierta trasera y paracaídas","en":"Back shell and parachute"},"fate":{"es":"Quedaron juntos en el suelo, y desde la órbita la cubierta trasera se ve casi sin daños y se distinguen los pliegues de la tela del paracaídas.","en":"They lie close together on the ground, and from orbit the back shell looks almost undamaged and the folds of the parachute cloth can be seen."},"where":"onMars","src":"https://science.nasa.gov/photojournal/mars-exploration-rover-landing-site-at-gusev-crater/"},{"name":{"es":"Módulo de aterrizaje con airbags","en":"Lander with airbags"},"fate":{"es":"Spirit llegó dentro de este módulo envuelto en bolsas de aire, bajó de él y lo dejó vacío en el cráter Gusev, donde una foto de 2006 tomada desde la órbita lo muestra.","en":"Spirit arrived inside this lander wrapped in airbags, drove off it and left it empty in Gusev crater, where a 2006 photo taken from orbit shows it."},"where":"onMars","src":"https://science.nasa.gov/photojournal/mars-exploration-rover-landing-site-at-gusev-crater/"}]},"opportunity":{"rocket":"delta7925H","site":"cape","pad":"SLC-17B","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"Opportunity espera en la punta de un Delta II pesado de 39,6 metros. Sus nueve propulsores son más anchos que los del cohete de Spirit y empujan alrededor de un 25 por ciento más.","en":"Opportunity waits on top of a heavy Delta II, 39.6 meters tall. Its nine boosters are wider than the ones on Spirit's rocket and give about 25 percent more thrust."},"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"liftoff","t":0,"title":{"es":"Despegue de noche","en":"A night liftoff"},"text":{"es":"El 7 de julio de 2003, a las 23:18 de Florida (ya era 8 de julio en hora universal), el Delta II despega de Cabo Cañaveral. Opportunity sigue a su gemelo Spirit, que ya viaja a Marte.","en":"On July 7, 2003, at 11:18 p.m. in Florida (already July 8 in universal time), the Delta II lifts off from Cape Canaveral. Opportunity follows its twin Spirit, already bound for Mars."},"ignite":["stage1","srbGround"],"src":"https://www.jpl.nasa.gov/news/newly-launched-opportunity-follows-mars-bound-spirit/"},{"id":"srbGround","t":82.5,"title":{"es":"Se sueltan seis propulsores","en":"Six boosters drop off"},"text":{"es":"Poco más de 80 segundos después del despegue, a unos 26 km de altura, los seis propulsores grandes ya están vacíos. Se sueltan de a tres y caen al océano Atlántico. Se encienden los otros tres.","en":"A little over 80 seconds after liftoff, about 26 km up, the six big boosters are empty. They let go in sets of three and fall into the Atlantic Ocean. The other three light up."},"drop":["srbGround"],"ignite":["srbAir"],"alt_km":26.1,"src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"id":"srbAir","t":161.5,"title":{"es":"Los últimos tres","en":"The last three"},"text":{"es":"Unos 2 minutos y 40 segundos después del despegue, a casi 70 km de altura, se sueltan los tres últimos propulsores, ya vacíos, y caen al Atlántico.","en":"About 2 minutes 40 seconds after liftoff, almost 70 km up, the last three boosters, now empty, drop off and fall into the Atlantic."},"drop":["srbAir"],"alt_km":68.9,"src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"id":"meco","t":263,"title":{"es":"Se va la primera etapa","en":"First stage falls away"},"text":{"es":"Unos 4 minutos y 23 segundos después del despegue el motor principal se apaga. En los 20 segundos siguientes la primera etapa se separa y cae al Atlántico, y se enciende la segunda etapa.","en":"About 4 minutes 23 seconds after liftoff the main engine shuts down. Within the next 20 seconds the first stage separates and falls into the Atlantic, and the second stage lights."},"drop":["stage1","interstage"],"ignite":["stage2"],"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"fairing","t":null,"title":{"es":"Se abre la cofia","en":"The nose cone opens"},"text":{"es":"En los 20 segundos que siguen al apagado del motor principal, la cofia que protegía a Opportunity durante la subida se desprende. Sus dos mitades caen al océano Atlántico.","en":"In the 20 seconds after the main engine shuts down, the nose cone that shielded Opportunity on the way up falls away. Its two halves fall into the Atlantic Ocean."},"drop":["fairingA","fairingB"],"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"parking","t":540,"title":{"es":"Una hora de espera","en":"An hour of waiting"},"text":{"es":"Unos 9 minutos después del despegue la segunda etapa se apaga. Opportunity gira alrededor de la Tierra a 167 km de altura durante alrededor de una hora. Después la etapa se enciende otra vez por 2 o 3 minutos.","en":"About 9 minutes after liftoff the second stage shuts down. Opportunity circles Earth 167 km up for about an hour. Then the stage fires again for 2 to 3 minutes."},"alt_km":167,"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"injection","t":null,"title":{"es":"La tercera etapa gira","en":"The third stage spins"},"text":{"es":"Más de una hora después del despegue, unos cohetes chicos hacen girar la tercera etapa a unas 63 vueltas por minuto. Se separa de la segunda, que queda en órbita de la Tierra, y empuja unos 87 segundos rumbo a Marte.","en":"More than an hour after liftoff, small rockets spin the third stage to about 63 turns per minute. It separates from the second stage, which stays in Earth orbit, and burns about 87 seconds on course for Mars."},"drop":["stage2"],"ignite":["stage3"],"src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"id":"separation","t":4980,"title":{"es":"Opportunity sigue por su cuenta","en":"Opportunity on its own"},"text":{"es":"Unas pesas con cables, como yoyós, frenan el giro. A los 83 minutos del despegue, Opportunity se separa de la tercera etapa, que queda dando vueltas al Sol.","en":"Weights on cables, like yo-yos, slow the spin. 83 minutes after liftoff Opportunity separates from the third stage, which is left circling the Sun."},"drop":["stage3"],"src":"https://www.jpl.nasa.gov/news/newly-launched-opportunity-follows-mars-bound-spirit/"}],"fates":[{"part":"srbGround","name":{"es":"Seis propulsores encendidos en tierra","en":"Six ground-lit boosters"},"fate":{"es":"Más anchos que los de un Delta II común, se soltaron de a tres poco más de 80 segundos después del despegue y cayeron al océano Atlántico.","en":"Wider than those of a standard Delta II, they were dropped in sets of three a little over 80 seconds after liftoff and fell into the Atlantic Ocean."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"srbAir","name":{"es":"Tres propulsores encendidos en vuelo","en":"Three air-lit boosters"},"fate":{"es":"Se encendieron en pleno vuelo, se soltaron unos 2 minutos y 40 segundos después del despegue y cayeron al océano Atlántico.","en":"They lit in flight, were dropped about 2 minutes 40 seconds after liftoff and fell into the Atlantic Ocean."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage1","name":{"es":"Primera etapa","en":"First stage"},"fate":{"es":"Funcionó unos 4 minutos y 23 segundos, se separó y cayó al océano Atlántico.","en":"It burned for about 4 minutes 23 seconds, separated and fell into the Atlantic Ocean."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"interstage","name":{"es":"Anillo entre etapas","en":"Interstage ring"},"fate":{"es":"Este anillo une la primera etapa con la segunda; los documentos de la NASA que leímos no dicen qué pasó con él en este vuelo.","en":"This ring joins the first stage to the second; the NASA documents we read do not say what happened to it on this flight."},"where":"unknown","src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"part":"fairingA","name":{"es":"Cofia (primera mitad)","en":"Nose cone (first half)"},"fate":{"es":"La cofia que cubría la nave se abrió en dos mitades poco después de apagarse el motor principal, y esta mitad cayó al océano Atlántico.","en":"The nose cone that covered the spacecraft split into two halves soon after the main engine shut down, and this half fell into the Atlantic Ocean."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingB","name":{"es":"Cofia (segunda mitad)","en":"Nose cone (second half)"},"fate":{"es":"Era la segunda mitad de la cofia y cayó al océano Atlántico igual que la primera.","en":"It was the second half of the nose cone and fell into the Atlantic Ocean just like the first."},"where":"ocean","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage2","name":{"es":"Segunda etapa","en":"Second stage"},"fate":{"es":"Después de su segundo encendido quedó en una órbita alargada alrededor de la Tierra y volvió a caer en la atmósfera el 25 de julio de 2004, según el catálogo de satélites de Estados Unidos.","en":"After its second burn it stayed in a stretched orbit around Earth and fell back into the atmosphere on 25 July 2004, according to the U.S. satellite catalog."},"where":"burned","src":"https://celestrak.org/satcat/table-satcat.php?INTDES=2003-032"},{"part":"stage3","name":{"es":"Tercera etapa (Star 48B)","en":"Third stage (Star 48B)"},"fate":{"es":"Después de empujar unos 87 segundos siguió viaje por un camino elegido a propósito para no chocar con Marte, y quedó en órbita alrededor del Sol.","en":"After its 87-second burn it flew on along a path chosen on purpose to miss Mars, and it stayed in orbit around the Sun."},"where":"sunOrbit","src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"}],"left":[{"name":{"es":"Etapa de crucero","en":"Cruise stage"},"fate":{"es":"Dio electricidad y corrigió el rumbo durante el viaje, se soltó 15 minutos antes de entrar en la atmósfera y, según el plan de la misión, terminó chocando contra Marte.","en":"It gave power and steered during the trip, was cast off 15 minutes before entering the atmosphere and, according to the mission plan, ended up hitting Mars."},"where":"marsImpact","src":"https://www.jpl.nasa.gov/news/press_kits/merlaunch.pdf"},{"name":{"es":"Escudo térmico","en":"Heat shield"},"fate":{"es":"Se rompió al golpear el suelo, y en una foto tomada desde la órbita en 2006 se ven el lugar del impacto y sus restos.","en":"It broke when it hit the ground, and a photo taken from orbit in 2006 shows the impact point and its broken remains."},"where":"onMars","src":"https://science.nasa.gov/photojournal/mars-exploration-rover-landing-site-at-meridiani-planum/"},{"name":{"es":"Cubierta trasera y paracaídas","en":"Back shell and parachute"},"fate":{"es":"El paracaídas quedó tendido en el suelo con la cubierta trasera, que tiene forma de cono, a su lado, como muestra una foto tomada desde la órbita en 2006.","en":"The parachute lies on the ground with the cone-shaped back shell next to it, as a photo taken from orbit in 2006 shows."},"where":"onMars","src":"https://science.nasa.gov/photojournal/mars-exploration-rover-landing-site-at-meridiani-planum/"},{"name":{"es":"Módulo de aterrizaje con airbags","en":"Lander with airbags"},"fate":{"es":"El módulo envuelto en bolsas de aire se detuvo dentro del cráter Eagle; Opportunity bajó de él y el módulo vacío se sigue viendo en el fondo del cráter en una foto de 2006 tomada desde la órbita.","en":"The lander wrapped in airbags came to rest inside Eagle crater; Opportunity drove off it and the empty lander is still visible on the crater floor in a 2006 photo taken from orbit."},"where":"onMars","src":"https://science.nasa.gov/photojournal/mars-exploration-rover-landing-site-at-meridiani-planum/"}]},"phoenix":{"rocket":"delta7925","site":"cape","pad":"SLC-17A","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"Phoenix espera en la punta de un cohete Delta II 7925 de 39,6 metros. La primera etapa lleva nueve propulsores de unos 13 metros de alto cada uno.","en":"Phoenix waits on top of a Delta II 7925 rocket 39.6 meters tall. The first stage carries nine solid boosters, each about 13 meters tall."},"src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"},{"id":"liftoff","t":0,"title":{"es":"Despegue antes del amanecer","en":"Liftoff before dawn"},"text":{"es":"El 4 de agosto de 2007, a las 5:26 de la mañana de Florida, el Delta II despega de Cabo Cañaveral hacia el cielo todavía oscuro del este.","en":"On August 4, 2007, at 5:26 in the morning in Florida, the Delta II lifts off from Cape Canaveral into the still-dark eastern sky."},"ignite":["stage1","srbGround"],"src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-landing.pdf"},{"id":"srbGround","t":null,"title":{"es":"Se sueltan seis propulsores","en":"Six boosters drop off"},"text":{"es":"Alrededor de un minuto después del despegue, los primeros seis propulsores ya están vacíos y se sueltan. Se encienden los otros tres. En general, en los Delta II estas piezas caen al océano.","en":"About a minute after liftoff the first six boosters are empty and drop off. The other three light up. In general, on Delta II rockets these pieces fall into the ocean."},"drop":["srbGround"],"ignite":["srbAir"],"src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"},{"id":"srbAir","t":null,"title":{"es":"Los últimos tres","en":"The last three"},"text":{"es":"Alrededor de un minuto más tarde se sueltan los tres últimos propulsores, ya vacíos. En general, en los Delta II también caen al océano.","en":"About a minute later the last three boosters, now empty, drop off. In general, on Delta II rockets they also fall into the ocean."},"drop":["srbAir"],"src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"},{"id":"meco","t":263,"title":{"es":"Se va la primera etapa","en":"First stage falls away"},"text":{"es":"Unos 4 minutos y 23 segundos después del despegue, a unos 111 km de altura, el motor principal se apaga. La primera etapa se separa y se enciende la segunda. En general, la primera etapa cae al océano.","en":"About 4 minutes 23 seconds after liftoff, about 111 km up, the main engine shuts down. The first stage separates and the second stage lights. In general, the first stage falls into the ocean."},"drop":["stage1","interstage"],"ignite":["stage2"],"alt_km":111,"src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"},{"id":"fairing","t":null,"title":{"es":"Se abre la cofia","en":"The nose cone opens"},"text":{"es":"En los 40 segundos que siguen al apagado del motor principal, la cofia que protegía a Phoenix del aire se desprende. En general, en los Delta II sus dos mitades caen al océano.","en":"In the 40 seconds after the main engine shuts down, the nose cone that shielded Phoenix from the air falls away. In general, on Delta II rockets its two halves fall into the ocean."},"drop":["fairingA","fairingB"],"src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"},{"id":"parking","t":560,"title":{"es":"La espera más larga","en":"The longest wait"},"text":{"es":"Cerca de los 9 minutos y 20 segundos la segunda etapa se apaga. Phoenix rodea la Tierra a 167 km de altura más de una hora, la espera más larga de un Delta II hasta entonces. Luego la etapa se enciende unos 2 minutos.","en":"At about 9 minutes 20 seconds the second stage shuts down. Phoenix circles Earth 167 km up for more than an hour, the longest wait of any Delta II until then. Then the stage fires for about 2 minutes."},"alt_km":167,"src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"},{"id":"injection","t":null,"title":{"es":"La tercera etapa gira","en":"The third stage spins"},"text":{"es":"Más de una hora después del despegue, unos cohetes chicos hacen girar la tercera etapa a unas 70 vueltas por minuto. Se separa de la segunda, que queda en órbita de la Tierra, y empuja unos 87 segundos rumbo a Marte.","en":"More than an hour after liftoff, small rockets spin the third stage to about 70 turns per minute. It separates from the second stage, which stays in Earth orbit, and burns about 87 seconds on course for Mars."},"drop":["stage2"],"ignite":["stage3"],"src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"},{"id":"separation","t":5040,"title":{"es":"Phoenix sigue por su cuenta","en":"Phoenix on its own"},"text":{"es":"Unas pesas con cables, como yoyós, frenan el giro y Phoenix se separa de la tercera etapa, que queda dando vueltas al Sol. En el plan del primer día posible era a los 84 minutos; según el día, entre 82 y 96.","en":"Weights on cables, like yo-yos, slow the spin and Phoenix separates from the third stage, which is left circling the Sun. In the plan for the first possible day that came at 84 minutes; depending on the day, 82 to 96."},"drop":["stage3"],"src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"}],"fates":[{"part":"srbGround","name":{"es":"Seis propulsores encendidos en tierra","en":"Six ground-lit boosters"},"fate":{"es":"Se soltaron vacíos cerca de un minuto después del despegue; en general, las carcasas de estos propulsores del Delta II caen al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"They dropped away empty about a minute after liftoff; in general, the casings of these Delta II boosters fall into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"srbAir","name":{"es":"Tres propulsores encendidos en vuelo","en":"Three air-lit boosters"},"fate":{"es":"Se encendieron cuando los primeros seis se apagaron y se soltaron alrededor de un minuto más tarde; en general, estas carcasas caen al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"They lit when the first six burned out and were dropped about a minute later; in general, these casings fall into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage1","name":{"es":"Primera etapa","en":"First stage"},"fate":{"es":"Funcionó unos 4 minutos y 23 segundos y se separó; en general, la primera etapa del Delta II cae al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"It burned for about 4 minutes 23 seconds and separated; in general, the Delta II first stage falls into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"interstage","name":{"es":"Anillo entre etapas","en":"Interstage ring"},"fate":{"es":"Este anillo une la primera etapa con la segunda; los documentos de la NASA que leímos no dicen qué pasó con él en este vuelo.","en":"This ring joins the first stage to the second; the NASA documents we read do not say what happened to it on this flight."},"where":"unknown","src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"},{"part":"fairingA","name":{"es":"Cofia (primera mitad)","en":"Nose cone (first half)"},"fate":{"es":"Se soltó junto con la otra mitad poco después de apagarse el motor principal; en general, las mitades de la cofia del Delta II caen al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"It dropped away together with the other half soon after the main engine shut down; in general, the halves of the Delta II nose cone fall into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingB","name":{"es":"Cofia (segunda mitad)","en":"Nose cone (second half)"},"fate":{"es":"Se soltó junto con la primera mitad poco después de apagarse el motor principal; en general, las mitades de la cofia del Delta II caen al océano, pero los documentos de la NASA que leímos no lo dicen para este vuelo.","en":"It dropped away together with the first half soon after the main engine shut down; in general, the halves of the Delta II nose cone fall into the ocean, but the NASA documents we read do not say so for this flight."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage2","name":{"es":"Segunda etapa","en":"Second stage"},"fate":{"es":"Después de su segundo encendido quedó en una órbita alargada alrededor de la Tierra y volvió a caer en la atmósfera el 6 de junio de 2010, según el catálogo de satélites de Estados Unidos.","en":"After its second burn it stayed in a stretched orbit around Earth and fell back into the atmosphere on 6 June 2010, according to the U.S. satellite catalog."},"where":"burned","src":"https://celestrak.org/satcat/table-satcat.php?INTDES=2007-034"},{"part":"stage3","name":{"es":"Tercera etapa (Star 48B)","en":"Third stage (Star 48B)"},"fate":{"es":"Por diseño nunca apuntó a Marte: después de empujar unos 87 segundos siguió de largo y quedó en órbita alrededor del Sol.","en":"By design it was never aimed at Mars: after its 87-second burn it flew on past and stayed in orbit around the Sun."},"where":"sunOrbit","src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"}],"left":[{"name":{"es":"Etapa de crucero","en":"Cruise stage"},"fate":{"es":"Llevó los paneles solares del viaje, se soltó minutos antes de entrar en la atmósfera y, según el plan de la misión, la atravesó hasta chocar contra Marte.","en":"It carried the solar panels for the trip, was cast off minutes before entering the atmosphere and, according to the mission plan, plunged through it and hit Mars."},"where":"marsImpact","src":"https://www.jpl.nasa.gov/news/press_kits/phoenix-launch-presskit.pdf"},{"name":{"es":"Escudo térmico","en":"Heat shield"},"fate":{"es":"Se soltó mientras Phoenix bajaba colgada del paracaídas, y una foto tomada desde la órbita lo muestra en el suelo junto a la marca que dejó al rebotar.","en":"It was dropped while Phoenix hung under its parachute, and a photo taken from orbit shows it on the ground next to the mark it left when it bounced."},"where":"onMars","src":"https://science.nasa.gov/photojournal/connecting-the-dots-lander-heat-shield-parachute/"},{"name":{"es":"Cubierta trasera y paracaídas","en":"Back shell and parachute"},"fate":{"es":"Phoenix los soltó para terminar de bajar con sus motores, y una foto tomada desde la órbita muestra el paracaídas todavía unido a la cubierta trasera en el suelo.","en":"Phoenix let go of them to finish the descent on its engines, and a photo taken from orbit shows the parachute still attached to the back shell on the ground."},"where":"onMars","src":"https://science.nasa.gov/photojournal/connecting-the-dots-lander-heat-shield-parachute/"}]},"near":{"rocket":"delta7925","site":"cape","pad":"LC-17B","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"17 de febrero de 1996, plataforma 17B de Cabo Cañaveral. NEAR espera en la punta de un Delta II de tres etapas.","en":"17 February 1996, pad 17B at Cape Canaveral. NEAR waits on top of a three-stage Delta II."},"src":"https://nssdc.gsfc.nasa.gov/planetary/mission/near/near_traj.html"},{"id":"liftoff","t":0,"title":{"es":"Despegue de NEAR","en":"NEAR lifts off"},"text":{"es":"A las 15:43, hora de Florida (20:43 en hora universal), NEAR despega rumbo al asteroide Eros.","en":"At 3:43 p.m. Florida time (20:43 Universal Time), NEAR lifts off, bound for the asteroid Eros."},"ignite":["stage1","srbGround"],"src":"https://nssdc.gsfc.nasa.gov/planetary/mission/near/near_traj.html"},{"id":"srbGround","t":null,"title":{"es":"Seis cohetes menos","en":"Six boosters gone"},"text":{"es":"En un Delta II 7925, seis de los nueve cohetes laterales arden desde el despegue. Cuando se gastan, se encienden los otros tres y los seis vacíos se sueltan. En general, estas piezas caen al océano.","en":"On a Delta II 7925, six of the nine strap-on boosters burn from liftoff. When they run out, the other three light up and the six empty ones drop away. In general, these pieces fall into the ocean."},"drop":["srbGround"],"ignite":["srbAir"],"src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"id":"srbAir","t":null,"title":{"es":"Los últimos tres","en":"The last three"},"text":{"es":"Los últimos tres cohetes laterales también se gastan y se sueltan. En general, caen al océano como los primeros.","en":"The last three boosters run out too and drop away. In general, they fall into the ocean like the first ones."},"drop":["srbAir"],"src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"id":"stage1","t":null,"title":{"es":"Adiós, primera etapa","en":"Goodbye, first stage"},"text":{"es":"El motor principal se apaga y la primera etapa se separa. El plan era encender la segunda etapa a 122 km de altura. En general, la primera etapa del Delta II cae al océano.","en":"The main engine shuts down and the first stage separates. The plan was to light the second stage 122 km up. In general, the Delta II first stage falls into the ocean."},"drop":["stage1","interstage"],"ignite":["stage2"],"alt_km":122,"src":"https://www.govinfo.gov/content/pkg/FR-1996-01-24/html/96-917.htm"},{"id":"fairing","t":null,"title":{"es":"Se suelta la cofia","en":"The nose cone drops"},"text":{"es":"Con la segunda etapa ya encendida, la cofia que protegía a NEAR se suelta. En general, en los Delta II sus mitades caen al océano.","en":"With the second stage already burning, the nose cone that protected NEAR drops away. In general, on a Delta II its halves fall into the ocean."},"drop":["fairingA","fairingB"],"src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"id":"parking","t":600,"title":{"es":"Órbita de espera","en":"A parking orbit"},"text":{"es":"Unos 10 minutos después del despegue, NEAR entra en una órbita de espera a 183 km de altura. Ahí avanza 13 minutos con los motores apagados.","en":"About 10 minutes after liftoff, NEAR enters a parking orbit 183 km up. It coasts there for 13 minutes with the engines off."},"alt_km":183,"src":"https://nssdc.gsfc.nasa.gov/planetary/mission/near/near_traj.html"},{"id":"stage2","t":null,"title":{"es":"El empujón final","en":"The final push"},"text":{"es":"Después de esos 13 minutos llega el empujón final, de unos 4 minutos, hecho sobre todo por la tercera etapa, de combustible sólido. La segunda etapa quedó en órbita baja hasta caer a la atmósfera.","en":"After those 13 minutes comes the final push: about 4 minutes, done mostly by the solid-fuel third stage. The second stage stayed in low orbit until it fell into the atmosphere."},"drop":["stage2"],"ignite":["stage3"],"src":"https://nssdc.gsfc.nasa.gov/planetary/mission/near/near_traj.html"},{"id":"separation","t":null,"title":{"es":"NEAR vuela sola","en":"NEAR flies alone"},"text":{"es":"NEAR se separa de la tercera etapa. Un yoyó de cables frena su giro, de hasta 69 vueltas por minuto, y libera los paneles solares. Según el catálogo espacial de EE. UU., la etapa quedó en órbita solar.","en":"NEAR separates from the third stage. A yo-yo of cables stops its spin, up to 69 turns per minute, and frees the solar panels. According to the US space catalogue, the stage was left in orbit around the Sun."},"drop":["stage3"],"src":"https://nssdc.gsfc.nasa.gov/planetary/mission/near/near_traj.html"}],"fates":[{"part":"srbGround","name":{"es":"Seis cohetes laterales encendidos en tierra","en":"Six ground-lit strap-on boosters"},"fate":{"es":"Se soltaron vacíos poco después de apagarse; según la NASA, en los Delta II las carcasas de estos cohetes caen al océano.","en":"They dropped away empty soon after burning out; NASA says that on a Delta II the casings of these boosters fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"srbAir","name":{"es":"Tres cohetes laterales encendidos en vuelo","en":"Three air-lit strap-on boosters"},"fate":{"es":"Se soltaron vacíos después de los seis primeros; según la NASA, en los Delta II estas carcasas caen al océano.","en":"They dropped away empty after the first six; NASA says that on a Delta II these casings fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage1","name":{"es":"Primera etapa","en":"First stage"},"fate":{"es":"Se separó cuando se apagó el motor principal; según la NASA, la primera etapa de los Delta II cae al océano.","en":"It separated when the main engine shut down; NASA says the Delta II first stage falls into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"interstage","name":{"es":"Anillo entre etapas","en":"Interstage ring"},"fate":{"es":"Es el tubo que une la primera etapa con la segunda; en los Delta II forma parte de la primera etapa, que según la NASA cae al océano.","en":"It is the tube that joins the first stage to the second; on a Delta II it is part of the first stage, which NASA says falls into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingA","name":{"es":"Cofia, primera mitad","en":"Nose cone, first half"},"fate":{"es":"Se soltó junto con la otra mitad poco después de encenderse la segunda etapa; según la NASA, las mitades de la cofia de los Delta II caen al océano.","en":"It dropped away together with the other half soon after the second stage lit up; NASA says the halves of the Delta II nose cone fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingB","name":{"es":"Cofia, segunda mitad","en":"Nose cone, second half"},"fate":{"es":"Se soltó junto con la otra mitad poco después de encenderse la segunda etapa; según la NASA, las mitades de la cofia de los Delta II caen al océano.","en":"It dropped away together with the other half soon after the second stage lit up; NASA says the halves of the Delta II nose cone fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage2","name":{"es":"Segunda etapa","en":"Second stage"},"fate":{"es":"Quedó en órbita baja alrededor de la Tierra hasta que su órbita decayó y volvió a entrar en la atmósfera, tal como lo había previsto la NASA antes del lanzamiento.","en":"It stayed in low orbit around Earth until its orbit decayed and it re-entered the atmosphere, just as NASA had planned before the launch."},"where":"burned","src":"https://www.govinfo.gov/content/pkg/FR-1996-01-24/html/96-917.htm"},{"part":"stage3","name":{"es":"Tercera etapa (motor Star 48)","en":"Third stage (Star 48 motor)"},"fate":{"es":"Sacó a NEAR de la órbita terrestre y, según el catálogo de objetos espaciales de Estados Unidos, quedó en órbita alrededor del Sol.","en":"It pushed NEAR out of Earth orbit and, according to the United States catalogue of space objects, it was left in orbit around the Sun."},"where":"sunOrbit","src":"https://celestrak.org/satcat/table-satcat.php?INTDES=1996-008"}],"left":[]},"dawn":{"rocket":"delta7925H","site":"cape","pad":"SLC-17B","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"27 de septiembre de 2007, plataforma 17B de Cabo Cañaveral. Dawn espera en la punta de un Delta II con nueve cohetes laterales, guardada dentro de la cofia.","en":"27 September 2007, pad 17B at Cape Canaveral. Dawn waits on top of a Delta II with nine strap-on boosters, tucked inside the nose cone."},"src":"https://www.jpl.nasa.gov/news/dawn-spacecraft-successfully-launched/"},{"id":"liftoff","t":0,"title":{"es":"Despegue de Dawn","en":"Dawn lifts off"},"text":{"es":"A las 7:34 de la mañana, hora de Florida, se encienden el motor principal de la primera etapa y seis de los nueve cohetes laterales.","en":"At 7:34 in the morning, Florida time, the first stage main engine and six of the nine strap-on boosters light up."},"ignite":["stage1","srbGround"],"src":"https://www.jpl.nasa.gov/news/press_kits/dawn-launch.pdf"},{"id":"srbGround","t":80.5,"title":{"es":"Seis cohetes menos","en":"Six boosters gone"},"text":{"es":"A los 77 segundos, a unos 24 km de altura, los seis cohetes se apagan. Se encienden los otros tres y los seis vacíos se sueltan. En general, en los Delta II estas piezas caen al océano.","en":"At 77 seconds, about 24 km up, the six boosters burn out. The other three light up and the six empty ones drop away. In general, on a Delta II these pieces fall into the ocean."},"drop":["srbGround"],"ignite":["srbAir"],"src":"https://www.jpl.nasa.gov/blog/2007/9/september-12-2007"},{"id":"srbAir","t":159.5,"title":{"es":"Los últimos tres","en":"The last three"},"text":{"es":"Los últimos tres cohetes laterales arden 77 segundos y se sueltan a casi 73 km de altura, cuando el cohete va a unas diez veces la velocidad del sonido. En general, también caen al océano.","en":"The last three boosters burn for 77 seconds and drop away almost 73 km up, with the rocket flying at about ten times the speed of sound. In general, they fall into the ocean too."},"drop":["srbAir"],"alt_km":73,"src":"https://www.jpl.nasa.gov/blog/2007/9/september-12-2007"},{"id":"stage1","t":271,"title":{"es":"Adiós, primera etapa","en":"Goodbye, first stage"},"text":{"es":"El motor principal se apaga a los 4 minutos y 23 segundos. Poco después, a 130 km de altura, la primera etapa se separa y se enciende la segunda. En general, la primera etapa cae al océano.","en":"The main engine shuts down at 4 minutes 23 seconds. Soon after, 130 km up, the first stage separates and the second one lights up. In general, the first stage falls into the ocean."},"drop":["stage1","interstage"],"ignite":["stage2"],"alt_km":130,"src":"https://www.jpl.nasa.gov/blog/2007/9/september-12-2007"},{"id":"fairing","t":281,"title":{"es":"Se suelta la cofia","en":"The nose cone drops"},"text":{"es":"A los 4 minutos y 41 segundos, a 135 km de altura, ya no hace falta la cofia que protegía a Dawn del aire, y se suelta. En general, en los Delta II sus mitades caen al océano.","en":"At 4 minutes 41 seconds, 135 km up, the nose cone that shielded Dawn from the air is no longer needed, and it drops away. In general, on a Delta II its halves fall into the ocean."},"drop":["fairingA","fairingB"],"alt_km":135,"src":"https://www.jpl.nasa.gov/news/press_kits/dawn-launch.pdf"},{"id":"parking","t":538,"title":{"es":"En órbita baja","en":"In low orbit"},"text":{"es":"A los 8 minutos y 58 segundos la segunda etapa se apaga: Dawn ya está en órbita baja alrededor de la Tierra. El cohete avanza 42 minutos y 37 segundos con el motor apagado.","en":"At 8 minutes 58 seconds the second stage shuts down: Dawn is now in a low orbit around Earth. The rocket coasts for 42 minutes 37 seconds with its engine off."},"src":"https://www.jpl.nasa.gov/news/press_kits/dawn-launch.pdf"},{"id":"stage2","t":3308,"title":{"es":"Otro empujón","en":"Another push"},"text":{"es":"La segunda etapa se enciende 2 minutos y 39 segundos más. Dawn y la tercera etapa se ponen a girar a unas 50 vueltas por minuto y la segunda se separa y queda atrás, en órbita alrededor de la Tierra.","en":"The second stage fires for 2 minutes 39 seconds more. Dawn and the third stage are spun up to about 50 turns per minute and the second stage separates and stays behind, in orbit around Earth."},"drop":["stage2"],"ignite":["stage3"],"src":"https://www.jpl.nasa.gov/news/press_kits/dawn-launch.pdf"},{"id":"separation","t":3721,"title":{"es":"Dawn vuela sola","en":"Dawn flies alone"},"text":{"es":"La tercera etapa arde 86 segundos y Dawn escapa de la Tierra. Un yoyó de cables frena el giro y, a 62 minutos del despegue y 1.021 km de altura, Dawn se suelta. La etapa siguió sola, alrededor del Sol.","en":"The third stage burns for 86 seconds and Dawn escapes from Earth. A yo-yo of cables stops the spin and, 62 minutes after liftoff and 1,021 km up, Dawn lets go. The stage went on alone, around the Sun."},"drop":["stage3"],"alt_km":1021,"src":"https://www.jpl.nasa.gov/blog/2007/9/september-12-2007"}],"fates":[{"part":"srbGround","name":{"es":"Seis cohetes laterales encendidos en tierra","en":"Six ground-lit strap-on boosters"},"fate":{"es":"Se soltaron vacíos a los 80,5 y 81,5 segundos del despegue; según la NASA, en los Delta II las carcasas de estos cohetes caen al océano.","en":"They dropped away empty 80.5 and 81.5 seconds after liftoff; NASA says that on a Delta II the casings of these boosters fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"srbAir","name":{"es":"Tres cohetes laterales encendidos en vuelo","en":"Three air-lit strap-on boosters"},"fate":{"es":"Se soltaron vacíos a los 2 minutos y 39,5 segundos, a casi 73 km de altura; según la NASA, en los Delta II estas carcasas caen al océano.","en":"They dropped away empty at 2 minutes 39.5 seconds, almost 73 km up; NASA says that on a Delta II these casings fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage1","name":{"es":"Primera etapa","en":"First stage"},"fate":{"es":"Se separó a los 4 minutos y 31 segundos, a unos 130 km de altura; según la NASA, la primera etapa de los Delta II cae al océano.","en":"It separated at 4 minutes 31 seconds, about 130 km up; NASA says the Delta II first stage falls into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"interstage","name":{"es":"Anillo entre etapas","en":"Interstage ring"},"fate":{"es":"Es el tubo que une la primera etapa con la segunda; en los Delta II forma parte de la primera etapa, que según la NASA cae al océano.","en":"It is the tube that joins the first stage to the second; on a Delta II it is part of the first stage, which NASA says falls into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingA","name":{"es":"Cofia, primera mitad","en":"Nose cone, first half"},"fate":{"es":"Se soltó junto con la otra mitad a los 4 minutos y 41 segundos, a 135 km de altura; según la NASA, las mitades de la cofia de los Delta II caen al océano.","en":"It dropped away together with the other half at 4 minutes 41 seconds, 135 km up; NASA says the halves of the Delta II nose cone fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingB","name":{"es":"Cofia, segunda mitad","en":"Nose cone, second half"},"fate":{"es":"Se soltó junto con la otra mitad a los 4 minutos y 41 segundos, a 135 km de altura; según la NASA, las mitades de la cofia de los Delta II caen al océano.","en":"It dropped away together with the other half at 4 minutes 41 seconds, 135 km up; NASA says the halves of the Delta II nose cone fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage2","name":{"es":"Segunda etapa","en":"Second stage"},"fate":{"es":"Se separó a los 55 minutos del despegue y quedó dando vueltas a la Tierra hasta que, según el catálogo de objetos espaciales de Estados Unidos, volvió a entrar en la atmósfera el 18 de septiembre de 2009.","en":"It separated 55 minutes after liftoff and kept circling Earth until, according to the United States catalogue of space objects, it re-entered the atmosphere on 18 September 2009."},"where":"burned","src":"https://celestrak.org/satcat/table-satcat.php?INTDES=2007-043"},{"part":"stage3","name":{"es":"Tercera etapa (motor Star 48)","en":"Third stage (Star 48 motor)"},"fate":{"es":"Después de soltar a Dawn siguió sola por el sistema solar, en órbita alrededor del Sol, igual que los dos cables con pesas del yoyó que frenó el giro.","en":"After releasing Dawn it went on alone through the solar system, in orbit around the Sun, and so did the two weighted yo-yo cables that stopped the spin."},"where":"sunOrbit","src":"https://www.jpl.nasa.gov/blog/2007/9/september-12-2007"}],"left":[]},"kepler":{"rocket":"delta7925_10L","site":"cape","pad":"SLC-17B","steps":[{"id":"pad","t":null,"title":{"es":"En la plataforma","en":"On the pad"},"text":{"es":"Noche del 6 de marzo de 2009, plataforma 17B de Cabo Cañaveral. El telescopio Kepler espera en la punta de un Delta II, dentro de una cofia de 3 metros de ancho.","en":"Night of 6 March 2009, pad 17B at Cape Canaveral. The Kepler telescope waits on top of a Delta II, inside a nose cone 3 metres wide."},"src":"https://www.jpl.nasa.gov/news/press_kits/Kepler-presskit-2-19-smfile.pdf"},{"id":"liftoff","t":0,"title":{"es":"Despegue de noche","en":"A night liftoff"},"text":{"es":"A las 22:49, hora de Florida, se encienden el motor principal de la primera etapa y seis de los nueve cohetes laterales.","en":"At 10:49 p.m. Florida time, the first stage main engine and six of the nine strap-on boosters light up."},"ignite":["stage1","srbGround"],"src":"https://www.jpl.nasa.gov/news/press_kits/Kepler-presskit-2-19-smfile.pdf"},{"id":"srbGround","t":66,"title":{"es":"Seis cohetes menos","en":"Six boosters gone"},"text":{"es":"Los seis cohetes se apagan a los 63,1 segundos. A los 65,5 se encienden los otros tres y enseguida los seis vacíos se sueltan, de a tres. En general, en los Delta II estas piezas caen al océano.","en":"The six boosters burn out at 63.1 seconds. At 65.5 the other three light up and right after the six empty ones drop away, three at a time. In general, on a Delta II these pieces fall into the ocean."},"drop":["srbGround"],"ignite":["srbAir"],"alt_km":18.1,"src":"https://www.ulalaunch.com/docs/default-source/news-items/dii_kepler_mob.pdf"},{"id":"srbAir","t":131.5,"title":{"es":"Los últimos tres","en":"The last three"},"text":{"es":"Los últimos tres cohetes laterales se sueltan a los 131,5 segundos, a unos 57 km de altura. En general, también caen al océano.","en":"The last three boosters drop away at 131.5 seconds, about 57 km up. In general, they fall into the ocean too."},"drop":["srbAir"],"alt_km":57,"src":"https://www.ulalaunch.com/docs/default-source/news-items/dii_kepler_mob.pdf"},{"id":"stage1","t":271.3,"title":{"es":"Adiós, primera etapa","en":"Goodbye, first stage"},"text":{"es":"El motor principal arde casi 4 minutos y medio. Después la primera etapa se separa y, unos 5 segundos más tarde, se enciende la segunda. En general, la primera etapa cae al océano.","en":"The main engine burns for almost 4 and a half minutes. Then the first stage separates and, about 5 seconds later, the second one lights up. In general, the first stage falls into the ocean."},"drop":["stage1","interstage"],"ignite":["stage2"],"src":"https://www.ulalaunch.com/docs/default-source/news-items/dii_kepler_mob.pdf"},{"id":"fairing","t":281,"title":{"es":"Se suelta la cofia","en":"The nose cone drops"},"text":{"es":"A los 4,7 minutos de vuelo, a unos 135 km de altura, el aire ya casi no calienta al cohete y la cofia se suelta. En general, en los Delta II sus mitades caen al océano.","en":"4.7 minutes into the flight, about 135 km up, the air hardly heats the rocket any more and the nose cone drops away. In general, on a Delta II its halves fall into the ocean."},"drop":["fairingA","fairingB"],"alt_km":135.4,"src":"https://www.jpl.nasa.gov/news/press_kits/Kepler-presskit-2-19-smfile.pdf"},{"id":"parking","t":596,"title":{"es":"En órbita baja","en":"In low orbit"},"text":{"es":"Poco antes de los 10 minutos la segunda etapa se apaga: Kepler está en una órbita circular a 185 km de altura. El cohete avanza unos 43 minutos sin motor, girando despacio como un asador.","en":"Just under 10 minutes in, the second stage shuts down: Kepler is in a circular orbit 185 km up. The rocket coasts for about 43 minutes, slowly rolling like a barbecue spit."},"alt_km":185,"src":"https://www.jpl.nasa.gov/news/press_kits/Kepler-presskit-2-19-smfile.pdf"},{"id":"stage2","t":3296.8,"title":{"es":"Otro empujón","en":"Another push"},"text":{"es":"La segunda etapa empuja 64 segundos más. Unos cohetes chicos ponen a girar a la tercera etapa con Kepler y la segunda se separa. Según el catálogo de objetos espaciales de Estados Unidos, sigue en órbita terrestre.","en":"The second stage pushes for 64 more seconds. Small rockets spin up the third stage with Kepler and the second stage separates. According to the United States catalogue of space objects, it is still in Earth orbit."},"drop":["stage2"],"ignite":["stage3"],"src":"https://www.ulalaunch.com/docs/default-source/news-items/dii_kepler_mob.pdf"},{"id":"separation","t":3708.8,"title":{"es":"Kepler vuela solo","en":"Kepler flies alone"},"text":{"es":"La tercera etapa arde casi 90 segundos. Unos 5 minutos después un yoyó frena el giro y Kepler se suelta, al sudeste de Nueva Guinea. Queda en órbita solar y, según el catálogo espacial de EE. UU., la etapa también.","en":"The third stage burns for almost 90 seconds. About 5 minutes later a yo-yo stops the spin and Kepler lets go southeast of New Guinea. It stays in solar orbit and, according to the US space catalogue, so does the stage."},"drop":["stage3"],"alt_km":721.5,"src":"https://www.jpl.nasa.gov/news/press_kits/Kepler-presskit-2-19-smfile.pdf"}],"fates":[{"part":"srbGround","name":{"es":"Seis cohetes laterales encendidos en tierra","en":"Six ground-lit strap-on boosters"},"fate":{"es":"Se soltaron vacíos a los 66 y 67 segundos del despegue, a unos 18 km de altura; según la NASA, en los Delta II las carcasas de estos cohetes caen al océano.","en":"They dropped away empty 66 and 67 seconds after liftoff, about 18 km up; NASA says that on a Delta II the casings of these boosters fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"srbAir","name":{"es":"Tres cohetes laterales encendidos en vuelo","en":"Three air-lit strap-on boosters"},"fate":{"es":"Se soltaron vacíos a los 131,5 segundos, a unos 57 km de altura; según la NASA, en los Delta II estas carcasas caen al océano.","en":"They dropped away empty at 131.5 seconds, about 57 km up; NASA says that on a Delta II these casings fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage1","name":{"es":"Primera etapa","en":"First stage"},"fate":{"es":"Se separó unos 4 minutos y medio después del despegue; según la NASA, la primera etapa de los Delta II cae al océano.","en":"It separated about 4 and a half minutes after liftoff; NASA says the Delta II first stage falls into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"interstage","name":{"es":"Anillo entre etapas","en":"Interstage ring"},"fate":{"es":"Es el tubo que une la primera etapa con la segunda; en los Delta II forma parte de la primera etapa, que según la NASA cae al océano.","en":"It is the tube that joins the first stage to the second; on a Delta II it is part of the first stage, which NASA says falls into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingA","name":{"es":"Cofia, primera mitad","en":"Nose cone, first half"},"fate":{"es":"Se soltó junto con la otra mitad a los 4,7 minutos de vuelo, a unos 135 km de altura; según la NASA, las mitades de la cofia de los Delta II caen al océano.","en":"It dropped away together with the other half 4.7 minutes into the flight, about 135 km up; NASA says the halves of the Delta II nose cone fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"fairingB","name":{"es":"Cofia, segunda mitad","en":"Nose cone, second half"},"fate":{"es":"Se soltó junto con la otra mitad a los 4,7 minutos de vuelo, a unos 135 km de altura; según la NASA, las mitades de la cofia de los Delta II caen al océano.","en":"It dropped away together with the other half 4.7 minutes into the flight, about 135 km up; NASA says the halves of the Delta II nose cone fall into the ocean."},"where":"unknown","src":"https://www.nasa.gov/wp-content/uploads/2018/04/mer_feis_dec_2002_0.pdf"},{"part":"stage2","name":{"es":"Segunda etapa","en":"Second stage"},"fate":{"es":"Después de soltar la tercera etapa quedó en una órbita alargada alrededor de la Tierra y, según el catálogo de objetos espaciales de Estados Unidos, sigue ahí.","en":"After releasing the third stage it was left in a stretched-out orbit around Earth and, according to the United States catalogue of space objects, it is still there."},"where":"earthOrbit","src":"https://celestrak.org/satcat/table-satcat.php?INTDES=2009-011"},{"part":"stage3","name":{"es":"Tercera etapa (motor Star 48B)","en":"Third stage (Star 48B motor)"},"fate":{"es":"Sacó a Kepler de la órbita terrestre y, según el catálogo de objetos espaciales de Estados Unidos, quedó igual que Kepler en órbita alrededor del Sol.","en":"It pushed Kepler out of Earth orbit and, according to the United States catalogue of space objects, it ended up like Kepler in orbit around the Sun."},"where":"sunOrbit","src":"https://celestrak.org/satcat/table-satcat.php?INTDES=2009-011"}],"left":[{"name":{"es":"Tapa contra el polvo del telescopio","en":"Telescope dust cover"},"fate":{"es":"Kepler la soltó el 7 de abril de 2009 para dejar entrar la luz de las estrellas: la tapa ovalada, de 1,7 por 1,3 metros, se alejó flotando y quedó en su propia órbita alrededor del Sol, parecida a la de Kepler.","en":"Kepler released it on 7 April 2009 to let the starlight in: the oval cover, 1.7 by 1.3 metres, drifted away and ended up in its own orbit around the Sun, similar to Kepler's."},"where":"sunOrbit","src":"https://www.jpl.nasa.gov/news/dust-cover-jettisoned-from-nasas-kepler-telescope/"}]},"insight":{"rocket":"atlasV401","site":"vandenberg","pad":"SLC-3E","steps":[{"id":"pad","t":null,"title":{"es":"Espera en California","en":"Waiting in California"},"text":{"es":"Un cohete Atlas V 401 de 57,3 metros de alto espera en la base Vandenberg, en California. Es el primer lanzamiento hacia otro planeta desde la costa oeste de Estados Unidos.","en":"An Atlas V 401 rocket, 57.3 metres tall, stands at Vandenberg Air Force Base in California. This is the first launch to another planet from the west coast of the United States."},"src":"https://www.jpl.nasa.gov/news/press_kits/insight/launch/facts/"},{"id":"liftoff","t":0,"title":{"es":"Despegue desde Vandenberg","en":"Liftoff from Vandenberg"},"text":{"es":"5 de mayo de 2018, 4:05 de la mañana en California. Se enciende el único motor RD-180 de la primera etapa, que quema querosén y oxígeno líquido, y el cohete se levanta de la plataforma.","en":"5 May 2018, 4:05 in the morning in California. The single RD-180 engine of the first stage lights up, burning kerosene and liquid oxygen, and lifts the rocket off the pad."},"ignite":["stage1"],"src":"https://science.nasa.gov/blogs/insight/2018/05/05/liftoff-atlas-v-clears-the-launch-pad-with-nasas-insight-spacecraft/"},{"id":"stage1","t":250,"title":{"es":"Se suelta la primera etapa","en":"First stage drops away"},"text":{"es":"A los 244 segundos el motor se apaga. Seis segundos después se sueltan la primera etapa, ya gastada, y los anillos que la unían al Centaur. Según el plan de la NASA, la etapa caería en el océano Pacífico.","en":"After 244 seconds the engine shuts down. Six seconds later the used-up first stage is let go, with the rings that joined it to the Centaur. NASA's launch plan said the stage would fall into the Pacific Ocean."},"drop":["stage1","interstage"],"src":"https://www.jpl.nasa.gov/news/press_kits/insight/launch/mission/"},{"id":"stage2","t":260,"title":{"es":"El Centaur toma el relevo","en":"Centaur takes over"},"text":{"es":"Diez segundos después de la separación, la etapa superior Centaur enciende su motor RL-10C. Quema hidrógeno y oxígeno líquidos, y puede apagarse y volver a encenderse en el espacio.","en":"Ten seconds after the stages separate, the Centaur upper stage lights its RL-10C engine. It burns liquid hydrogen and liquid oxygen, and it can be shut down and restarted in space."},"ignite":["stage2"],"src":"https://www.jpl.nasa.gov/news/press_kits/insight/launch/mission/"},{"id":"fairing","t":268,"title":{"es":"Se abre la cofia","en":"The nose cone opens"},"text":{"es":"Ocho segundos después, ya por encima de casi todo el aire, el cohete suelta las dos mitades de la cofia que cubría a InSight. El dossier de la NASA no dice dónde cayeron.","en":"Eight seconds later, above most of the air, the rocket drops the two halves of the nose cone that covered InSight. NASA's launch kit does not say where they came down."},"drop":["fairingA","fairingB"],"src":"https://www.jpl.nasa.gov/news/press_kits/insight/launch/mission/"},{"id":"orbit","t":796,"title":{"es":"Órbita de espera","en":"Parked around Earth"},"text":{"es":"A los 13 minutos y 16 segundos el Centaur apaga su motor. Ya está dando vueltas a la Tierra a 185 km de altura y sigue así, sin motor, durante cerca de una hora.","en":"13 minutes and 16 seconds after launch the Centaur shuts down its engine. It is now circling Earth at a height of 185 km, and it coasts like that for about an hour."},"alt_km":185,"src":"https://www.jpl.nasa.gov/news/bound-for-mars-countdown-to-first-interplanetary-launch-from-california/"},{"id":"tmi","t":4740,"title":{"es":"Segundo encendido, rumbo a Marte","en":"Second burn, toward Mars"},"text":{"es":"A 1 hora y 19 minutos del despegue el Centaur vuelve a encender su motor, cerca del Polo Norte. Unos cinco minutos de empuje sacan a InSight de la órbita terrestre y la mandan rumbo a Marte.","en":"One hour and 19 minutes after launch the Centaur lights its engine again, close to the North Pole. About five minutes of thrust send InSight out of Earth orbit and on its way to Mars."},"ignite":["stage2"],"src":"https://www.jpl.nasa.gov/news/bound-for-mars-countdown-to-first-interplanetary-launch-from-california/"},{"id":"separation","t":5580,"title":{"es":"InSight queda libre","en":"InSight flies free"},"text":{"es":"A unos 93 minutos del despegue, unos resortes separan a InSight del Centaur. Enseguida el Centaur suelta dos pequeños CubeSats, MarCO-A y MarCO-B, y se aparta. Como nunca apuntó a Marte, queda dando vueltas al Sol.","en":"About 93 minutes after liftoff, springs push InSight away from the Centaur. Soon after, the Centaur releases two small CubeSats, MarCO-A and MarCO-B, and steers aside. Never aimed at Mars, it stays circling the Sun."},"drop":["stage2"],"src":"https://www.jpl.nasa.gov/news/bound-for-mars-countdown-to-first-interplanetary-launch-from-california/"}],"fates":[{"part":"stage1","name":{"es":"Primera etapa (Common Core Booster)","en":"First stage (Common Core Booster)"},"fate":{"es":"Según el plan de lanzamiento de la NASA, esta etapa de 32,5 metros de largo se soltaría unos cuatro minutos después del despegue y caería en el océano Pacífico.","en":"NASA's launch plan said this stage, 32.5 metres long, would be let go about four minutes after liftoff and fall into the Pacific Ocean."},"where":"ocean","src":"https://www.jpl.nasa.gov/news/press_kits/insight/launch/mission/"},{"part":"interstage","name":{"es":"Adaptador entre etapas","en":"Interstage adapter"},"fate":{"es":"El dossier de lanzamiento de la NASA dice que los dos anillos adaptadores que unían la primera etapa con el Centaur también se sueltan cuando las etapas se separan, pero no dice dónde cayeron.","en":"NASA's launch kit says the two adapter rings that joined the first stage to the Centaur also fall away when the stages separate, but it does not say where they came down."},"where":"unknown","src":"https://www.jpl.nasa.gov/news/press_kits/insight/launch/mission/"},{"part":"fairingA","name":{"es":"Cofia, primera mitad","en":"Payload fairing, first half"},"fate":{"es":"Se soltó a los 268 segundos del lanzamiento; el dossier de la NASA no dice dónde cayó y, en general, las piezas que se sueltan antes de llegar a la órbita vuelven a caer a la Tierra.","en":"It was dropped 268 seconds after launch; NASA's launch kit does not say where it came down, and in general parts dropped before the rocket reaches orbit fall back to Earth."},"where":"unknown","src":"https://www.jpl.nasa.gov/news/press_kits/insight/launch/mission/"},{"part":"fairingB","name":{"es":"Cofia, segunda mitad","en":"Payload fairing, second half"},"fate":{"es":"Se soltó a los 268 segundos del lanzamiento; el dossier de la NASA no dice dónde cayó y, en general, las piezas que se sueltan antes de llegar a la órbita vuelven a caer a la Tierra.","en":"It was dropped 268 seconds after launch; NASA's launch kit does not say where it came down, and in general parts dropped before the rocket reaches orbit fall back to Earth."},"where":"unknown","src":"https://www.jpl.nasa.gov/news/press_kits/insight/launch/mission/"},{"part":"stage2","name":{"es":"Etapa superior Centaur","en":"Centaur upper stage"},"fate":{"es":"Después de soltar a InSight y a los dos MarCO, salió de la Tierra por casi el mismo camino que InSight pero, como planeó la NASA, sin apuntar nunca a Marte, así que quedó en órbita alrededor del Sol.","en":"After releasing InSight and the two MarCOs it left Earth on almost the same path as InSight but, as NASA planned, never aimed at Mars, so it stays in orbit around the Sun."},"where":"sunOrbit","src":"https://www.jpl.nasa.gov/news/press_kits/insight/landing/mission/spacecraft/"}],"left":[{"name":{"es":"Etapa de crucero","en":"Cruise stage"},"fate":{"es":"InSight la soltó siete minutos antes de llegar a la atmósfera de Marte, y la NASA esperaba que atravesara el aire, calentándose mucho, y chocara contra Marte.","en":"InSight let it go seven minutes before reaching Mars's atmosphere, and NASA expected it to plunge through the air, getting very hot, and hit Mars."},"where":"marsImpact","src":"https://www.jpl.nasa.gov/news/press_kits/insight/landing/mission/spacecraft/"},{"name":{"es":"Escudo térmico","en":"Heat shield"},"fate":{"es":"InSight lo soltó mientras colgaba del paracaídas, y en diciembre de 2018 la cámara HiRISE, en órbita de Marte, lo fotografió en el suelo, a unos cientos de metros del módulo.","en":"InSight dropped it while hanging from its parachute, and in December 2018 the HiRISE camera in Mars orbit photographed it on the ground, a few hundred metres from the lander."},"where":"onMars","src":"https://www.jpl.nasa.gov/news/mars-insight-lander-seen-in-first-images-from-space/"},{"name":{"es":"Carcasa trasera y paracaídas","en":"Back shell and parachute"},"fate":{"es":"El módulo los soltó a 1 km del suelo, más o menos, y en diciembre de 2018 la cámara HiRISE fotografió el paracaídas tendido en Marte, a unos cientos de metros del módulo.","en":"The lander let go of them about 1 km above the ground, and in December 2018 the HiRISE camera photographed the parachute lying on Mars, a few hundred metres from the lander."},"where":"onMars","src":"https://www.jpl.nasa.gov/news/mars-insight-lander-seen-in-first-images-from-space/"},{"name":{"es":"CubeSats MarCO-A y MarCO-B","en":"MarCO-A and MarCO-B CubeSats"},"fate":{"es":"Pasaron junto a Marte el 26 de noviembre de 2018 y siguieron de largo; la NASA los escuchó por última vez el 29 de diciembre de 2018 (MarCO-B) y el 4 de enero de 2019 (MarCO-A), y los dos están en órbita alrededor del Sol.","en":"They flew past Mars on 26 November 2018 and kept going; NASA last heard from MarCO-B on 29 December 2018 and from MarCO-A on 4 January 2019, and both are in orbit around the Sun."},"where":"sunOrbit","src":"https://www.jpl.nasa.gov/news/the-marco-mission-comes-to-an-end/"}]},"ingenuity":{"rocket":"atlasV541","site":"cape","pad":"SLC-41","steps":[{"id":"pad","t":null,"title":{"es":"Listo en Cabo Cañaveral","en":"Ready at Cape Canaveral"},"text":{"es":"Un cohete Atlas V 541 de 60 metros de alto espera en el Complejo de Lanzamiento 41. Dentro de la cofia, la punta del cohete, viajan el rover Perseverance y, sujeto a su panza, el helicóptero Ingenuity.","en":"An Atlas V 541 rocket, 60 metres tall, stands at Space Launch Complex 41. Inside its nose cone ride the Perseverance rover and, attached to its belly, the Ingenuity helicopter."},"src":"https://www.jpl.nasa.gov/news/press_kits/mars_2020/launch/mission/"},{"id":"liftoff","t":0,"title":{"es":"Despegue con cuatro propulsores","en":"Liftoff with four boosters"},"text":{"es":"30 de julio de 2020, 7:50 de la mañana en Florida. El motor principal RD-180 y cuatro propulsores de combustible sólido, sujetos a la primera etapa, levantan juntos al cohete.","en":"30 July 2020, 7:50 in the morning in Florida. The RD-180 main engine and four solid rocket boosters strapped to the first stage lift the rocket off the pad together."},"ignite":["stage1","srbGround"],"src":"https://www.nasa.gov/news-release/nasa-ula-launch-mars-2020-perseverance-rover-mission-to-red-planet/"},{"id":"srbGround","t":109.3,"title":{"es":"Se sueltan los propulsores","en":"Boosters fall away"},"text":{"es":"Al minuto y 49 segundos se sueltan los cuatro propulsores, ya gastados. No encontramos dónde cayeron. Un estudio de la NASA para esta misión dice que la trayectoria del cohete iba sobre el océano Atlántico.","en":"At 1 minute 49 seconds the four spent boosters are let go. We could not find where they landed. A NASA study for this mission says the rocket's path ran over the Atlantic Ocean."},"drop":["srbGround"],"src":"https://www.ulalaunch.com/docs/default-source/launch-booklets/mars2020_mobrochure_200717.pdf"},{"id":"fairing","t":207.6,"title":{"es":"Se suelta la cofia","en":"Nose cone comes off"},"text":{"es":"A los 3 minutos y 28 segundos, con la primera etapa aún encendida, se sueltan las dos mitades de la cofia de 5 metros, que cubría a la nave y al Centaur. No encontramos dónde cayeron.","en":"At 3 minutes 28 seconds, with the first stage still firing, the two halves of the 5-metre nose cone that covered the spacecraft and the Centaur are dropped. We could not find where they fell."},"drop":["fairingA","fairingB"],"src":"https://www.ulalaunch.com/docs/default-source/launch-booklets/mars2020_mobrochure_200717.pdf"},{"id":"stage1","t":268.1,"title":{"es":"Se suelta la primera etapa","en":"First stage lets go"},"text":{"es":"El RD-180 se apaga a los 4 minutos y 22 segundos y la primera etapa se separa seis segundos después. En el lanzamiento de Curiosity, con el mismo tipo de cohete, la NASA dijo que esta etapa cae en el Atlántico.","en":"The RD-180 shuts down at 4 minutes 22 seconds and the first stage separates six seconds later. For Curiosity's launch on the same type of rocket, NASA said this stage drops into the Atlantic Ocean."},"drop":["stage1"],"src":"https://www.ulalaunch.com/docs/default-source/launch-booklets/mars2020_mobrochure_200717.pdf"},{"id":"stage2","t":278.1,"title":{"es":"Se enciende el Centaur","en":"Centaur lights up"},"text":{"es":"Diez segundos después de la separación, la etapa superior Centaur enciende su único motor RL10, que quema hidrógeno y oxígeno líquidos. Este primer encendido dura casi siete minutos.","en":"Ten seconds after separation the Centaur upper stage starts its single RL10 engine, which burns liquid hydrogen and liquid oxygen. This first burn lasts almost seven minutes."},"ignite":["stage2"],"src":"https://www.ulalaunch.com/docs/default-source/launch-booklets/mars2020_mobrochure_200717.pdf"},{"id":"orbit","t":687.9,"title":{"es":"Órbita de espera","en":"Coasting around Earth"},"text":{"es":"A los 11 minutos y 28 segundos el Centaur se apaga. Ya está en una órbita de espera alrededor de la Tierra y sigue así, con el motor apagado, cerca de media hora.","en":"At 11 minutes 28 seconds the Centaur shuts down. It is now in a parking orbit around Earth, and it coasts with its engine off for about half an hour."},"src":"https://www.ulalaunch.com/docs/default-source/launch-booklets/mars2020_mobrochure_200717.pdf"},{"id":"tmi","t":2699.5,"title":{"es":"El empujón hacia Marte","en":"The push to Mars"},"text":{"es":"A los 45 minutos el motor del Centaur se enciende por segunda vez, durante casi ocho minutos. Este encendido le da a la nave la velocidad que necesita para dejar la Tierra y salir rumbo a Marte.","en":"At 45 minutes the Centaur's engine fires a second time, for almost eight minutes. This burn gives the spacecraft the speed it needs to leave Earth and head for Mars."},"ignite":["stage2"],"src":"https://www.ulalaunch.com/docs/default-source/launch-booklets/mars2020_mobrochure_200717.pdf"},{"id":"separation","t":3452.8,"title":{"es":"Perseverance queda libre","en":"Perseverance flies free"},"text":{"es":"A los 57 minutos y medio del despegue la nave se separa del Centaur. La NASA apuntó el Centaur para que no llegara a Marte, porque no estaba tan limpio como la nave. Por eso quedó dando vueltas al Sol.","en":"57 and a half minutes after liftoff the spacecraft separates from the Centaur. NASA aimed the Centaur to miss Mars on purpose, because it was not cleaned like the spacecraft. So it stays circling the Sun."},"drop":["stage2"],"src":"https://www.ulalaunch.com/docs/default-source/launch-booklets/mars2020_mobrochure_200717.pdf"}],"fates":[{"part":"srbGround","name":{"es":"Cuatro propulsores de combustible sólido","en":"Four solid rocket boosters"},"fate":{"es":"Se soltaron 1 minuto y 49 segundos después del despegue; no encontramos dónde cayeron, aunque un estudio de la NASA para esta misión dice que la trayectoria del cohete iba sobre el océano Atlántico.","en":"They were let go 1 minute 49 seconds after liftoff; we could not find where they landed, though a NASA study for this mission says the rocket's path ran over the Atlantic Ocean."},"where":"unknown","src":"https://www.nasa.gov/sites/default/files/atoms/files/mars_2020_public_draft_seis.pdf"},{"part":"fairingA","name":{"es":"Cofia, primera mitad","en":"Payload fairing, first half"},"fate":{"es":"Se soltó a los 3 minutos y 28 segundos del despegue; no encontramos dónde cayó, aunque un estudio de la NASA para esta misión dice que la trayectoria del cohete iba sobre el océano Atlántico.","en":"It was dropped 3 minutes 28 seconds after liftoff; we could not find where it fell, though a NASA study for this mission says the rocket's path ran over the Atlantic Ocean."},"where":"unknown","src":"https://www.nasa.gov/sites/default/files/atoms/files/mars_2020_public_draft_seis.pdf"},{"part":"fairingB","name":{"es":"Cofia, segunda mitad","en":"Payload fairing, second half"},"fate":{"es":"Se soltó a los 3 minutos y 28 segundos del despegue; no encontramos dónde cayó, aunque un estudio de la NASA para esta misión dice que la trayectoria del cohete iba sobre el océano Atlántico.","en":"It was dropped 3 minutes 28 seconds after liftoff; we could not find where it fell, though a NASA study for this mission says the rocket's path ran over the Atlantic Ocean."},"where":"unknown","src":"https://www.nasa.gov/sites/default/files/atoms/files/mars_2020_public_draft_seis.pdf"},{"part":"stage1","name":{"es":"Primera etapa (Common Core Booster)","en":"First stage (Common Core Booster)"},"fate":{"es":"Se separó a los 4 minutos y 28 segundos del despegue; no encontramos dónde cayó en este vuelo, pero para el lanzamiento de Curiosity, con el mismo tipo de cohete, la NASA dijo que la primera etapa cae en el océano Atlántico.","en":"It separated 4 minutes 28 seconds after liftoff; we could not find where it fell on this flight, but for Curiosity's launch on the same type of rocket NASA said the first stage drops into the Atlantic Ocean."},"where":"unknown","src":"https://www.jpl.nasa.gov/news/press_kits/MSLLaunch.pdf"},{"part":"stage2","name":{"es":"Etapa superior Centaur","en":"Centaur upper stage"},"fate":{"es":"La NASA apuntó el cohete por un camino que no llega a Marte y solo la nave corrigió después su rumbo hacia el planeta, así que el Centaur dejó la Tierra y quedó en órbita alrededor del Sol.","en":"NASA pointed the rocket along a path that does not meet Mars and only the spacecraft steered toward the planet afterwards, so the Centaur left Earth and stays in orbit around the Sun."},"where":"sunOrbit","src":"https://www.jpl.nasa.gov/news/press_kits/mars_2020/launch/mission/spacecraft/biological_cleanliness/"}],"left":[{"name":{"es":"Etapa de crucero","en":"Cruise stage"},"fate":{"es":"La nave la soltó unos 10 minutos antes de entrar en la atmósfera de Marte; un estudio de 2026, hecho con fotos tomadas desde la órbita, encontró que pedazos de esta etapa llegaron al suelo y abrieron cráteres de unos pocos metros al noroeste del cráter Jezero.","en":"The spacecraft shed it about 10 minutes before entering Mars's atmosphere; a 2026 study that used photos taken from orbit found that pieces of this stage reached the ground and dug craters a few metres across north-west of Jezero crater."},"where":"marsImpact","src":"https://doi.org/10.1029/2026GL122337"},{"name":{"es":"Escudo térmico","en":"Heat shield"},"fate":{"es":"Se desprendió 20 segundos después de que se abrió el paracaídas, y la cámara HiRISE, en órbita de Marte, lo fotografió en el suelo el 19 de febrero de 2021.","en":"It dropped away 20 seconds after the parachute opened, and the HiRISE camera in Mars orbit photographed it on the ground on 19 February 2021."},"where":"onMars","src":"https://www.jpl.nasa.gov/images/pia24333-perseverance-and-mars-2020-spacecraft-components-on-the-surface/"},{"name":{"es":"Carcasa trasera y paracaídas","en":"Back shell and parachute"},"fate":{"es":"Se separaron a unos 2,1 km del suelo y la carcasa chocó contra la superficie a unos 126 km/h; Ingenuity fotografió las dos piezas desde el aire el 19 de abril de 2022, en su vuelo 26.","en":"They separated about 2.1 km above the ground and the back shell hit the surface at about 126 km/h; Ingenuity photographed both from the air on 19 April 2022, during its Flight 26."},"where":"onMars","src":"https://www.jpl.nasa.gov/news/nasas-mars-helicopter-spots-gear-that-helped-perseverance-rover-land/"},{"name":{"es":"Etapa de descenso (grúa aérea)","en":"Descent stage (sky crane)"},"fate":{"es":"Después de bajar al rover con cuerdas se alejó volando para estrellarse a una distancia segura, y la cámara HiRISE fotografió su mancha de restos en forma de V el 19 de febrero de 2021.","en":"After lowering the rover on cords it flew off to crash at a safe distance, and the HiRISE camera photographed its V-shaped debris pattern on 19 February 2021."},"where":"marsImpact","src":"https://www.jpl.nasa.gov/images/pia24333-perseverance-and-mars-2020-spacecraft-components-on-the-surface/"},{"name":{"es":"Tapa protectora de Ingenuity","en":"Ingenuity's debris shield"},"fate":{"es":"Esta tapa protegió a Ingenuity bajo la panza del rover durante el aterrizaje, y Perseverance la soltó en el suelo el 21 de marzo de 2021.","en":"This cover protected Ingenuity under the rover's belly during the landing, and Perseverance dropped it on the ground on 21 March 2021."},"where":"onMars","src":"https://www.jpl.nasa.gov/images/pia24448-perseverance-rover-drops-its-debris-shield/"},{"name":{"es":"Rover Perseverance","en":"Perseverance rover"},"fate":{"es":"No está abandonado: la NASA lo cuenta como misión activa, todavía en funcionamiento y recorriendo la superficie de Marte (página actualizada el 14 de octubre de 2026).","en":"It is not abandoned: NASA lists it as an active mission, still operational and moving across the surface of Mars (page updated on 14 October 2026)."},"where":"onMars","src":"https://science.nasa.gov/mission/mars-2020-perseverance/"},{"name":{"es":"Helicóptero Ingenuity","en":"Ingenuity helicopter"},"fate":{"es":"Hizo 72 vuelos, el último el 18 de enero de 2024, cuando un daño en las palas del rotor lo dejó sin poder volar, y se quedó en Marte donde aterrizó por última vez.","en":"It made 72 flights, the last one on 18 January 2024, when damage to its rotor blades left it unable to fly, and it stays on Mars where it last landed."},"where":"onMars","src":"https://www.jpl.nasa.gov/news/after-three-years-on-mars-nasas-ingenuity-helicopter-mission-ends/"}]}};
